    /// Maximum number of threads for all internal thread pools.
    ///
    /// Caps Rayon global pool size, ONNX Runtime intra-op threads, and the
    /// combined document/inner-task budget for batch extraction. When `null`,
    /// the effective budget is `min(detected_cpu_cores, 8)` unless a Linux
    /// cgroup CPU quota is present, in which case the quota is used as the
    /// ceiling instead. On hosts with more than 8 cores and no cgroup quota,
    /// set `max_threads` explicitly to use the additional cores — the
    /// default will not scale past 8 on its own.
    max_threads: ?u64 = null,
    /// Maximum number of Tesseract recognition sessions that run at once.
    ///
    /// When `null`, recognition follows `max_threads`, reduced to the number
    /// of sessions the host's free memory holds. Each session keeps its own
    /// page image and recognition working set resident, so a host with many
    /// cores and little memory needs this lower than the thread budget. Set
    /// it to `4` to keep the fixed limit that releases up to 1.2.6 applied.
    ///
    /// A value set here is applied as given: neither the thread budget nor
    /// the memory reading reduces it. Both of those bound the automatic
    /// limit, and a caller who names a number has already decided what the
    /// host can carry.
    ///
    /// The first extraction in a process fixes the limit for the rest of that
    /// process, and a later extraction that names a different value keeps the
    /// first one. The two limiters that enforce it — the admission semaphore
    /// in the Tesseract backend and the handle pool behind it — are built once
    /// inside a backend the plugin registry holds for the life of the process,
    /// and the pool's capacity is fixed when it is constructed. A later value
    /// could therefore be reported but never enforced. Set it on the first
    /// extraction, or run one process per value.
    max_concurrent_ocr: ?u64 = null,
};

/// Cross-extractor content filtering configuration.
///
/// Controls whether "furniture" content (headers, footers, page numbers,
/// watermarks, repeating text) is included in or stripped from extraction
/// results. Applies across all extractors (PDF, DOCX, RTF, ODT, HTML, etc.)
/// with format-specific implementation.
///
/// When `null` on `ExtractionConfig`, each extractor uses its current
/// default behavior unchanged.
pub const ContentFilterConfig = struct {
    /// Include running headers in extraction output.
    ///
    /// - PDF: Disables top-margin furniture stripping and prevents the layout
    ///   model from treating `PageHeader`-classified regions as furniture.
    ///
    /// - DOC/DOCX: Includes document headers in text output.
    /// - RTF/ODT: Headers already included; this is a no-op when true.
    /// - HTML/EPUB: Keeps `<header>` element content.
    ///
    /// Default: `false` (headers are stripped or excluded).
    include_headers: bool,
    /// Include running footers in extraction output.
    ///
    /// - PDF: Disables bottom-margin furniture stripping and prevents the layout
    ///   model from treating `PageFooter`-classified regions as furniture.
    ///
    /// - DOC/DOCX: Includes document footers in text output.
    /// - RTF/ODT: Footers already included; this is a no-op when true.
    /// - HTML/EPUB: Keeps `<footer>` element content.
    ///
    /// Default: `false` (footers are stripped or excluded).
    include_footers: bool,
    /// Include footnote bodies in extraction output.
    ///
    /// - PDF: Prevents the layout model from treating `Footnote`-classified
    ///   regions as furniture, so footnote bodies survive alongside the main
    ///   text instead of being silently dropped.
    ///
    /// - DOC: Includes footnote definitions in extracted output.
    /// - Other formats: No effect currently.
    ///
    /// Default: `false` (footnotes are stripped), matching the existing
    /// `include_headers` / `include_footers` defaults.
    include_footnotes: bool,
    /// Enable the heuristic cross-page repeating text detector.
    ///
    /// When `true` (default), text that repeats verbatim across a supermajority
    /// of pages is classified as furniture and stripped. Disable this if brand
    /// names or repeated headings are being incorrectly removed by the heuristic.
    ///
    /// This flag also gates a same-page rule: a body paragraph is removed when
    /// its text is also carried by a table detected on the same page (catches
    /// table content that PDF extraction renders both as a table and as body
    /// text). The comparison preserves case and never touches headings, list
    /// items, code blocks, formulas, or captions, so it cannot delete a body
    /// sentence merely for repeating an earlier heading's words (GH#1623).
    ///
    /// Note: when a layout-detection model is active, the model may independently
    /// classify page-header / page-footer / footnote regions as furniture on a
    /// per-page basis. To preserve those regions, set `include_headers = true`,
    /// `include_footers = true`, `include_footnotes = true`, or any combination,
    /// in addition to disabling this flag.
    ///
    /// Primarily affects PDF extraction.
    ///
    /// Default: `true`.
    strip_repeating_text: bool,
    /// Include watermark text in extraction output.
    ///
    /// - PDF: Keeps watermark artifacts and arXiv identifiers.
    /// - Other formats: No effect currently.
    ///
    /// Default: `false` (watermarks are stripped).
    include_watermarks: bool,
};

/// JATS contributor with role.
pub const ContributorRole = struct {
    /// Contributor display name.
    name: []const u8,
    /// Contributor role (e.g. `"author"`, `"editor"`).
    role: ?[]const u8 = null,
};

/// Configuration for CSV/TSV extraction.
///
/// When unset (`ExtractionConfig.csv == None`), the extractor keeps its
/// existing default behavior: the delimiter is auto-detected by sampling the
/// file (comma, tab, pipe, or semicolon), and no line is treated as a comment.
pub const CsvConfig = struct {
    /// Field delimiter, as a single-character string (e.g. `","`, `";"`,
    /// `"\t"`, `"|"`). When `null` (default), the delimiter is auto-detected
    /// from a sample of the file.
    ///
    /// Must be exactly one ASCII byte when set — `ExtractionConfig.validate`
    /// rejects an empty string or a multi-byte value with a helpful error.
    /// The TSV MIME type (`text/tab-separated-values`) always forces `\t`
    /// regardless of this setting.
    delimiter: ?[]const u8 = null,
    /// Line prefixes that mark a comment line to skip entirely during row
    /// parsing (e.g. `["#"]`). A line is treated as a comment when its
    /// trimmed start matches any of these prefixes exactly.
    ///
    /// Default: empty, meaning no line is treated as a comment (matches the
    /// pre-existing extractor behavior).
    comment_prefixes: []const []const u8,
};

/// CSV/TSV file metadata.
pub const CsvMetadata = struct {
    /// Total number of data rows (excluding the header row if present).
    row_count: u32,
    /// Number of columns detected.
    column_count: u32,
    /// Field delimiter character (e.g. `","` or `"\t"`).
    delimiter: ?[]const u8 = null,
    /// Whether the first row was treated as a header.
    has_header: bool,
    /// Inferred data type for each column (e.g. `"string"`, `"integer"`, `"float"`).
    column_types: ?[]const []const u8 = null,
};

/// dBASE field information.
pub const DbfFieldInfo = struct {
