/// Per-file extraction configuration overrides for batch processing.
///
/// All fields are `Option<T>` — `null` means "use the batch-level default."
/// This type is used by `config` and `extract_batch`
/// to allow heterogeneous extraction settings within a single batch.
///
/// # Excluded Fields
///
/// The following `ExtractionConfig` fields are batch-level only and
/// cannot be overridden per file:
///
/// - `max_concurrent_extractions` — controls batch parallelism
/// - `use_cache` — global caching policy
/// - `acceleration` — shared ONNX execution provider
/// - `security_limits` — global archive security policy
pub const FileExtractionConfig = struct {
    /// Override MIME inference policy for this file.
    mime_detection_policy: ?MimeDetectionPolicy = null,
    /// Override quality post-processing for this file.
    enable_quality_processing: ?bool = null,
    /// Override OCR configuration for this file (None in the Option = use batch default).
    ocr: ?OcrConfig = null,
    /// Override force OCR for this file.
    force_ocr: ?bool = null,
    /// Override the OCR page-selection strategy for this file.
    ocr_strategy: ?OcrStrategy = null,
    /// Override force OCR pages for this file (1-indexed page numbers).
    force_ocr_pages: ?[]const u32 = null,
    /// Override disable OCR for this file.
    disable_ocr: ?bool = null,
    /// Override chunking configuration for this file.
    chunking: ?ChunkingConfig = null,
    /// Override content filtering configuration for this file.
    content_filter: ?ContentFilterConfig = null,
    /// Override image extraction configuration for this file.
    images: ?ImageExtractionConfig = null,
    /// Override token reduction for this file.
    token_reduction: ?TokenReductionOptions = null,
    /// Override language detection for this file.
    language_detection: ?LanguageDetectionConfig = null,
    /// Override page extraction for this file.
    pages: ?PageConfig = null,
    /// Override post-processor for this file.
    postprocessor: ?PostProcessorConfig = null,
    /// Override result format for this file.
    result_format: ?ResultFormat = null,
    /// Override output content format for this file.
    output_format: ?OutputFormat = null,
    /// Override document structure output for this file.
    include_document_structure: ?bool = null,
    /// Override strict parsing for this file.
    strict_parse: ?bool = null,
    /// Override per-file extraction timeout in seconds.
    ///
    /// When set, the extraction for this file will be canceled after the
    /// specified duration. A timed-out file produces an error result without
    /// affecting other files in the batch.
    timeout_secs: ?u64 = null,
    /// Override structured extraction configuration for this file.
    ///
    /// When set, enables LLM-based structured extraction with a JSON schema
    /// for this specific file. The extracted content is sent to a VLM/LLM
    /// and the response is parsed according to the provided schema.
    structured_extraction: ?StructuredExtractionConfig = null,
    /// Override URL ingestion and crawl configuration for this file.
    url: ?UrlExtractionConfig = null,
    /// Override named-entity recognition configuration for this file.
    ner: ?NerConfig = null,
    /// Override redaction configuration for this file.
    redaction: ?XbergRedactionConfig = null,
    /// Override summarization configuration for this file.
    summarization: ?SummarizationConfig = null,
    /// Override translation configuration for this file.
    translation: ?TranslationConfig = null,
    /// Override per-page classification configuration for this file.
    page_classification: ?PageClassificationConfig = null,
    /// Override per-chunk classification configuration for this file.
    chunk_classification: ?ChunkClassificationConfig = null,
    /// Override VLM captioning configuration for this file.
    captioning: ?CaptioningConfig = null,
    /// Override QR-code detection for this file.
    qr_codes: ?bool = null,
};

/// Footnote in Djot.
pub const Footnote = struct {
    /// Footnote label
    label: []const u8,
    /// Footnote content blocks
    content: []const FormattedBlock,
};

/// Block-level element in a Djot document.
///
/// Represents structural elements like headings, paragraphs, lists, code blocks, etc.
pub const FormattedBlock = struct {
    /// Type of block element
    block_type: BlockType,
    /// Heading level (1-6) for headings, or nesting level for lists
    level: ?u64 = null,
    /// Inline content within the block
    inline_content: []const InlineElement,
    /// Element attributes (classes, IDs, key-value pairs)
    attributes: ?Attributes = null,
    /// Language identifier for code blocks
    language: ?[]const u8 = null,
    /// Raw code content for code blocks
    code: ?[]const u8 = null,
    /// Nested blocks for containers (blockquotes, list items, divs)
    children: []const FormattedBlock,
};

/// A mathematical formula extracted from a document.
///
/// Three kinds of sources populate this type. Layout-guided OCR detects
/// formula regions and recognizes them; those formulas carry a `bbox` and a
/// `page`. VLM OCR recognizes formulas in transcribed text without layout, so
/// its formulas carry no geometry. Markup extraction (DOCX, PPTX, ODT, EPUB,
/// HTML, JATS, LaTeX, Markdown, and related formats) converts embedded math
/// to LaTeX, also without geometry.
pub const Formula = struct {
    /// LaTeX source of the formula, without surrounding `$$` delimiters.
    ///
    /// Markup converters and formula OCR produce real LaTeX. The native PDF
    /// layout path stores the plain text of a detected formula region, which
    /// keeps the original Unicode math characters instead of LaTeX commands.
    /// To render the formula in Markdown or other formats, wrap it in `$$..$$`.
    latex: []const u8,
    /// Bounding box of the formula region on its page. `null` for markup sources.
    ///
    /// PDF OCR sources report PDF point coordinates with the origin at the
    /// bottom-left of the page, comparable to native PDF geometry. Image
    /// sources, and PDF pages whose geometry is unavailable, report pixels of
    /// the image the OCR backend saw. The C FFI reports an absent bbox as a
    /// null pointer.
    bbox: ?BoundingBox = null,
    /// 1-indexed page number the formula appears on. `null` when the source
    /// format has no page concept. The C FFI reports an absent page as `0`.
    page: ?u32 = null,
};

/// Configuration for GeoJSON extraction.
///
/// GeoJSON coordinates can dominate extraction output and duplicate large geometry
/// payloads in rendered content and metadata. The default therefore emits a bounded
/// aggregate summary. Set `Self.include_full_coordinates` only when callers need
/// every coordinate in the extracted text and accept output proportional to the input.
pub const GeoJsonExtractionConfig = struct {
    /// Include every coordinate in rendered content and `flattened_fields` metadata.
    ///
    /// Defaults to `false`. When false, extraction reports feature, property, geometry,
    /// position-count, bounds, truncation, and discarded-category metadata and emits a
    /// `ProcessingWarning` for every GeoJSON input.
    include_full_coordinates: bool,
};

pub const GlossaryConfig = struct {
    enabled: bool,
    link_style: LinkStyle,
    /// Mentions detected below this confidence are not recorded.
    min_confidence: f32,
    /// Terms seen fewer than this many times are not published or linked.
    ///
    /// A glossary of one-off mentions is noise, and every published term is one more
    /// place a real name can resurface in a document that was supposed to be redacted.
    min_count: u64,
};

/// One glossary term and the evidence behind it.
pub const GlossaryEntry = struct {
    category: []const u8,
    term: []const u8,
    count: u64,
    /// Mean detection confidence across every observed mention.
    mean_confidence: f32,
};

pub const Governance = struct {
    organization: []const u8,
    review_process: []const u8,
    update_frequency: []const u8,
    changelog: []const []const u8,
};

/// Individual grid cell with position and span metadata.
pub const GridCell = struct {
    /// Cell text content.
    content: []const u8,
    /// Zero-indexed row position.
    row: u32,
    /// Zero-indexed column position.
    col: u32,
    /// Number of rows this cell spans.
    row_span: u32,
    /// Number of columns this cell spans.
    col_span: u32,
    /// Whether this is a header cell.
    is_header: bool,
    /// Bounding box for this cell (if available).
    bbox: ?BoundingBox = null,
    /// Outline level (1-6) of the heading style this cell's text carries, when it has one.
    ///
    /// A DOCX banner row -- row 0, one cell spanning the grid, styled `Heading1`..`Heading6` --
    /// is what Word's navigation pane and a `TOC` field treat as the document's outline, but as
    /// a table cell it reached consumers as anonymous text (GH#1587). `content` is deliberately
    /// left as the bare cell text: prefixing it with `#` would put a markdown heading inside a
    /// table cell, which is invalid where it lands and changes text every existing consumer
    /// already reads. This field is the signal instead, so a caller can decide for itself
    /// whether a `heading 2` in a banner row is a section title or a column label.
    heading_level: ?u8 = null,
    /// Human-readable name of the paragraph style applied to this cell's text (`heading 2`).
    ///
    /// Carries the style even when it resolves to no outline level, so a caller can key on a
    /// named style this library does not map to a heading. See `GridCell.heading_level`.
    style_name: ?[]const u8 = null,
};

/// # Unknown keys are rejected
///
/// This type and every hacienda-owned config below it carry `deny_unknown_fields`, so a
/// misspelt key fails the load instead of being discarded. Silently discarding produces
/// a file that says a control is configured and a process in which it is not — the
/// failure shape the CLI spec (§6.3) names as the most common "why is this not
/// redacting" incident.
///
/// The usual objection is forward compatibility: a file written for a newer hacienda
/// stops loading on an older one. That trade is already made for us — xberg's
/// `ExtractionConfig` declares `deny_unknown_fields`, so `[extraction]` is strict
/// today. Leaving hacienda's own sections permissive would make the section we do not
/// own the stricter one.
pub const HaciendaConfig = struct {
    extraction: ExtractionConfig,
    /// Which installation this process belongs to: `LocalFull` or `TeamOnPremise`.
    ///
    /// This is the first-class `[installation]` section of issue #142. It is the *same*
    /// type the desktop client reads from `HACIENDA_INSTALLATION_CONFIG`, resolved by
    /// `hacienda_installation.resolve_installation` and validated by
    /// `InstallationConfig.validate_for`, so client and server cannot grow two ideas
    /// of what an installation means (dossier `docs/wayfinder/131-installations.md` §I1,
    /// gap É1).
    ///
    /// `null` means no source declared one. That is correct for the one-shot commands —
    /// `hacienda extract` runs inside its own process boundary and needs no topology —
    /// but `hacienda serve` refuses to start without it: a network-facing process has to
    /// say which installation it is rather than be assumed to be one.
    installation: ?InstallationConfig = null,
    /// Detection and redaction. `null` extracts without touching PII.
    pii: ?PipelineConfig = null,
    compliance: ?ComplianceConfig = null,
    /// Human review queue for low-confidence detections.
    ///
    /// Requires `pii`: there is nothing to review without detections.
    review: ?ReviewConfig = null,
    glossary: ?GlossaryConfig = null,
    /// Authentication for `hacienda serve`. Disabled by default, which is correct for
    /// the CLI and the desktop app: there, the process boundary *is* the trust boundary.
    ///
    /// It is not a field the CLI reads — `hacienda extract` is always `Caller.Trusted`.
    /// It lives here so that one config file describes the whole product, and so that
    /// `hacienda serve` can refuse a non-loopback bind when it is off.
    auth: AuthConfig,
};

pub const HaciendaMetadata = struct {
    processing_time_ms: u64,
    pii_enabled: bool,
    documents: u64,
};

/// Everything one `HaciendaFacade.process` call produced.
pub const HaciendaResult = struct {
    /// The extraction envelope. When PII is enabled, every document's `content` has
    /// already been redacted — the raw text never leaves this call.
    extraction: ExtractionResult,
    /// One detection result per extracted document, in the same order.
    pii: []const PipelineResult,
    compliance: ?ComplianceReport = null,
    /// Audit entries appended by this call. The full chain lives in the facade.
    audit_entries: []const AuditEntry,
    /// Detections routed to human review by this call.
    review_submitted: u64,
    /// Glossary terms meeting the publication threshold, across every call so far.
    glossary: []const GlossaryEntry,
    metadata: HaciendaMetadata,
};

/// Header/heading element metadata.
