    root_cause: []const u8,
};

pub const IncidentResponse = struct {
    detected_at: []const u8,
    contained_at: ?[]const u8 = null,
    resolved_at: ?[]const u8 = null,
    actions_taken: []const []const u8,
    lessons_learned: []const []const u8,
};

/// Inline element within a block.
