    content: []const u8,
    /// Element attributes
    attributes: ?Attributes = null,
    /// Additional metadata (e.g., href for links, src/alt for images)
    metadata: ?std.StringHashMap([]const u8) = null,
};

/// JATS (Journal Article Tag Suite) metadata.
pub const JatsMetadata = struct {
    /// Copyright statement from the article's `<permissions>` element.
    copyright: ?[]const u8 = null,
    /// Open-access license URI from the article's `<license>` element.
    license: ?[]const u8 = null,
    /// Publication history dates keyed by event type (e.g. `"received"`, `"accepted"`).
    history_dates: std.StringHashMap([]const u8),
    /// Authors and contributors with their stated roles.
    contributor_roles: []const ContributorRole,
};

/// An async document-processing job.
///
/// Created by `create` and updated atomically via
/// `transition`, `finish`, and `fail`. Callers that need to stream progress or
/// implement retries should poll `get` — no push notification mechanism is defined
/// here, because no consumer exists yet.
pub const Job = struct {
    /// Stable identifier — UUID v4, assigned on creation.
    id: []const u8,
    /// Current lifecycle state.
    status: JobStatus,
    /// RFC 3339 timestamp when the job was created.
    created_at: []const u8,
    /// RFC 3339 timestamp of the most recent status change.
    updated_at: []const u8,
    /// Serialised result payload from the pipeline, populated on `Succeeded`.
    ///
    /// Stored as opaque JSON so the store layer does not depend on the pipeline's
    /// result type — a store that names `HaciendaResult` cannot be reused by any other
    /// pipeline, and `Arc<dyn JobStore>` cannot be generic. See plan D5.
    result_json: ?[]const u8 = null,
    /// Human-readable failure reason, populated on `Failed`.
    error_: ?[]const u8 = null,
    /// Serialised, pipeline-defined progress payload, updated in place by
    /// `JobStore.update_progress` while the job is `Running`.
    ///
    /// Opaque JSON for the same reason as `result_json`: the store layer must
    /// not depend on any one pipeline's progress shape. `null` until the
    /// pipeline reports its first progress update; a job that never reports
    /// progress (e.g. `/v1/documents/async`) simply never sets this field.
    progress_json: ?[]const u8 = null,
    /// Principal that created the job.
    ///
    /// `null` means the job was submitted by a trusted in-process caller (CLI,
    /// desktop app, test) — mirroring `Caller.Trusted` / `Caller.principal_id()`.
    /// The transport layer uses this to return 404 rather than 403 to a tenant who
    /// requests another tenant's job, preventing IDOR (OWASP A01). The store
    /// records the value; enforcement is the transport's responsibility.
    owner: ?[]const u8 = null,
    /// The tenant this job belongs to (S1). Unlike `owner` (a principal *within* a
    /// tenant, optional for trusted callers), every job has exactly one tenant —
    /// `Caller.Trusted`'s `tenant_ctx()` resolves to the `default` tenant, the same
    /// one every pre-S1 job is attributed to.
    ///
    /// Defaulted on deserialize (mirroring `review.types.ReviewQueueItem.tenant_id`):
    /// `Job` is not currently persisted via `serde_json` in any production backend, but
    /// carrying the same default keeps the type safe to serialize/deserialize should a
    /// future store do so.
    tenant_id: []const u8,
};

/// A string key-value attribute.
pub const KeyValueAttribute = struct {
    /// Attribute name.
    key: []const u8,
    /// Attribute value.
    value: []const u8,
};

/// Structured per-language detection result: confidence, document share, and script —
/// the information the ISO-code-only `detected_languages` list cannot convey (#261).
///
/// Populated by the language-detection processor alongside `detected_languages`, with one
/// entry per language, in the same order as `detected_languages`.
pub const LanguageConfidence = struct {
    /// ISO 639-3 language code, matching the corresponding entry in `detected_languages`.
    language: []const u8,
    /// Confidence for this language, in `[0.0, 1.0]`.
    ///
    /// In single-language mode this is whatlang's `Info.confidence()` for the whole
    /// document. In multi-language mode this is the average whatlang confidence across
    /// the document's 200-character chunks that were classified as this language.
    confidence: f64,
    /// Share of the document's analyzed content classified as this language, in `[0.0, 1.0]`.
    ///
    /// In single-language mode this is always `1.0`. In multi-language mode this is the
    /// fraction of 200-character chunks classified as this language (chunks that did not
    /// meet `min_confidence` for any language are excluded from the count but still count
    /// toward the denominator).
    proportion: f64,
    /// Writing system whatlang detected for this language (e.g. `"Latin"`, `"Cyrillic"`).
    script: []const u8,
    /// Whether this detection is considered reliable.
    ///
    /// In single-language mode this is whatlang's own `Info.is_reliable()` (confidence
    /// above whatlang's internal 0.9 threshold). In multi-language mode this is the
    /// chunk-averaged `confidence` above that same 0.9 threshold, since whatlang's
    /// `is_reliable()` only applies to a single detection.
    reliable: bool,
};

/// Language detection configuration.
pub const LanguageDetectionConfig = struct {
    /// Enable language detection
    enabled: bool,
    /// Minimum confidence threshold (0.0-1.0)
    min_confidence: f64,
    /// Detect multiple languages in the document
    detect_multiple: bool,
};

/// Configuration for the late-interaction (ColBERT) pipeline.
///
/// Controls which model to use, batching, and download/cache behavior for the
/// local ONNX ColBERT model.
pub const LateInteractionConfig = struct {
    /// The late-interaction model to use (defaults to the "gte-moderncolbert" preset).
    model: LateInteractionModelType,
    /// Batch size for local ONNX inference.
    ///
    /// ColBERT emits a `[seq, dim]` multi-vector embedding per document, so
    /// memory scales with batch size — keep this modest.
    batch_size: u64,
    /// Maximum token sequence length for the tokenizer (documents).
    max_length: u64,
    /// Fixed padded length for query augmentation.
    ///
    /// ColBERT queries are padded (with the mask token, kept attention-live)
    /// to exactly this many tokens rather than truncated/left as-is — this is
    /// the "query augmentation" trick from the ColBERT paper.
    query_max_length: u64,
    /// Show model download progress (local ONNX path only).
    ///
    /// When enabled, transfer progress for the model, tokenizer and config files is reported at
    /// `info` level on the `xberg.model_download` target while they download (#279). A warm
    /// Hugging Face cache transfers nothing and so reports nothing. Ignored by
    /// `LateInteractionModelType.Plugin`, which downloads no model.
    show_download_progress: bool,
    /// Optional alternate Hugging Face cache root for model files.
    ///
    /// When unset, hf-hub follows the standard Hugging Face environment and
    /// platform cache conventions.
    cache_dir: ?[]const u8 = null,
    /// Hardware acceleration for the late-interaction ONNX model.
    acceleration: ?AccelerationConfig = null,
    /// Maximum wall-clock duration (in seconds) for a single embed call when
    /// using `LateInteractionModelType.Plugin`. `null` disables the timeout.
    max_embed_duration_secs: ?u64 = null,
};

/// A detected layout region on a page.
