pub const MergeConfig = struct {
    /// Overlap ratio above which two spans are considered the same detection.
    overlap_threshold: f32,
    priority: MergePriority,
    /// Confidence difference required before a candidate displaces an existing span.
    confidence_epsilon: f32,
};

/// A detection after regex and model results have been reconciled.
pub const MergedEntity = struct {
    category: PiiCategory,
    /// Mention text. Empty for regex detections, which carry offsets only.
    text: []const u8,
    start: u32,
    end: u32,
    confidence: f32,
    source: EntitySource,
    format_preserving: bool,
    redact_template: []const u8,
};

/// Extraction result metadata.
///
/// Contains common fields applicable to all formats, format-specific metadata
/// via a discriminated union, and additional custom fields from postprocessors.
pub const Metadata = struct {
    /// Document title
    title: ?[]const u8 = null,
    /// Document subject or description
    subject: ?[]const u8 = null,
    /// Primary author(s) - always Vec for consistency
    authors: ?[]const []const u8 = null,
    /// Keywords/tags - always Vec for consistency
    keywords: ?[]const []const u8 = null,
    /// Primary language (ISO 639 code)
    language: ?[]const u8 = null,
    /// Creation timestamp (ISO 8601 format)
    created_at: ?[]const u8 = null,
    /// Last modification timestamp (ISO 8601 format)
    modified_at: ?[]const u8 = null,
    /// User who created the document
    created_by: ?[]const u8 = null,
    /// User who last modified the document
    modified_by: ?[]const u8 = null,
    /// Page/slide/sheet structure with boundaries
    pages: ?PageStructure = null,
    /// Format-specific metadata (discriminated union)
    ///
    /// Contains detailed metadata specific to the document format.
    /// Serialized as a nested `"format"` object with a `format_type` discriminator field.
    format: ?FormatMetadata = null,
    /// Image preprocessing metadata (when OCR preprocessing was applied)
    image_preprocessing: ?ImagePreprocessingMetadata = null,
    /// JSON schema (for structured data extraction)
    json_schema: ?[]const u8 = null,
    /// Error metadata (for batch operations)
    error_: ?ErrorMetadata = null,
    /// Extraction duration in milliseconds (for benchmarking).
    ///
    /// This field is populated by batch extraction to provide per-file timing
    /// information. It's `null` for single-file extraction (which uses external timing).
    extraction_duration_ms: ?u64 = null,
    /// Document category (from frontmatter or classification).
    category: ?[]const u8 = null,
    /// Document tags (from frontmatter).
    tags: ?[]const []const u8 = null,
    /// Document version string (from frontmatter).
    document_version: ?[]const u8 = null,
    /// Abstract or summary text (from frontmatter).
    abstract_text: ?[]const u8 = null,
    /// Output format identifier (e.g., "markdown", "html", "text").
    ///
    /// Set by the output format pipeline stage when format conversion is applied.
    /// Previously stored in `metadata.additional["output_format"]`.
    output_format: ?[]const u8 = null,
    /// Whether OCR was used during extraction.
    ///
    /// Set to `true` whenever the extraction pipeline ran an OCR backend
    /// (Tesseract, PaddleOCR, VLM, etc.) and used that output as the primary
    /// or fallback text. `false` means native text extraction was used exclusively.
    ocr_used: bool,
    /// Additional custom fields from postprocessors.
    ///
    /// Serialized as a nested `"additional"` object (not flattened at root level).
    /// Uses `Cow<'static, str>` keys so static string keys avoid allocation.
    additional: std.StringHashMap([]const u8),
};

pub const Metric = struct {
    name: []const u8,
    value: []const u8,
};

pub const ModelCard = struct {
    model_details: ModelDetails,
    training_data: TrainingData,
    evaluation: Evaluation,
    bias_fairness: BiasFairness,
    deployment: Deployment,
    governance: Governance,
};

/// Which NER model the statistical half of the pipeline runs, if any.
///
/// The model is loaded from a local directory rather than a hub id: detection runs
/// on-premise and must not reach the network at inference time.
pub const ModelConfig = struct {
    /// When false the pipeline is regex-only. Nothing is loaded.
    enabled: bool,
    /// Directory holding the GLiNER2 base weights, tokenizer, and config.
    model_dir: ?[]const u8 = null,
    /// Pinned model identity, e.g. `jamon8888/gliner2-guardrails-pii-f16`.
    ///
    /// When set, native loading verifies `model_dir` against the shared
    /// `hacienda-model-assets` registry before handing any bytes to Candle.
    /// `null` preserves the existing behaviour for privately fine-tuned models.
    model_id: ?[]const u8 = null,
    /// Directory holding a PEFT LoRA adapter to merge into the base weights at load.
    lora_adapter_dir: ?[]const u8 = null,
};

pub const ModelDetails = struct {
    name: []const u8,
    version: []const u8,
    description: []const u8,
    architecture: []const u8,
    parameters: []const u8,
    license: []const u8,
    contact: []const u8,
    date: []const u8,
};

/// A span produced by a statistical (NER model) backend.
pub const ModelEntity = struct {
    category: PiiCategory,
    text: []const u8,
    start: u32,
    end: u32,
    confidence: f32,
};

/// A ColBERT multi-vector embedding: one row per attention-live token.
///
/// `data` is a flat, row-major buffer of length `num_tokens * dim` — row `i`
/// (the embedding for token `i`) occupies `data[i*dim .. (i+1)*dim]`. Flat
/// storage keeps the type FFI-friendly across binding boundaries; use
/// `MultiVectorEmbedding.rows` internally to iterate per-token slices.
pub const MultiVectorEmbedding = struct {
    /// Number of attention-live token rows (padding rows are dropped, not
    /// zeroed — see `engine.normalize_tokens`).
    num_tokens: u32,
    /// Dimensionality of each per-token vector.
    dim: u32,
    /// Flat row-major buffer, length `num_tokens * dim`.
    data: []const f32,
};

/// Configuration for the NER post-processor.
pub const NerConfig = struct {
    /// Backend that runs the entity detection.
    backend: NerBackendKind = .onnx,
    /// Entity categories to detect. Defaults to a sensible PERSON/ORG/LOCATION/EMAIL set
    /// when empty.
    categories: []const EntityCategory,
    /// Override the default model — only used by `NerBackendKind.Onnx`.
    /// `null` lets the backend pick its pinned default xberg GLiNER model alias.
    model: ?[]const u8 = null,
    /// Optional LLM configuration — only used by `NerBackendKind.Llm`. Token usage
    /// for LLM backends is recorded in `ExtractedDocument.llm_usage`.
    llm: ?LlmConfig = null,
    /// Arbitrary user-supplied entity labels for zero-shot detection.
    ///
    /// `xberg-gliner` natively supports zero-shot inference over caller-supplied
    /// labels. The LLM backend also honours these
    /// labels by including them in the structured-output schema. Custom labels
    /// surface as `EntityCategory.Custom` in the resulting `Entity` stream.
    ///
    /// Use this when you need domain-specific entity types (e.g. `"Treatment"`,
    /// `"Product"`, `"Vessel"`) without forking GLiNER's taxonomy.
    custom_labels: []const []const u8,
};

/// Confidence scores for an OCR element.
///
/// Separates detection confidence (how confident that text exists at this location)
/// from recognition confidence (how confident about the actual text content).
pub const OcrConfidence = struct {
    /// Detection confidence: how confident the OCR engine is that text exists here.
    ///
    /// PaddleOCR provides this as `box_score`, Tesseract doesn't have a direct equivalent.
    /// Range: 0.0 to 1.0 (or None if not available).
    detection: ?f64 = null,
    /// Recognition confidence: how confident about the text content.
    ///
    /// Range: 0.0 to 1.0.
    recognition: f64,
};

/// OCR configuration.
pub const OcrConfig = struct {
    /// Whether OCR is enabled.
    ///
    /// Setting `enabled: false` is a shorthand for `disable_ocr: true` on the parent
    /// `ExtractionConfig`. Images return
    /// metadata only; PDFs use native text extraction without OCR fallback.
    ///
    /// Defaults to `true`. When `false`, all other OCR settings are ignored.
    enabled: bool,
    /// OCR backend: tesseract, paddleocr, paddle-ocr, sceptre, or vlm.
    /// Sceptre uses ONNX Runtime on desktop/server and tract on supported mobile builds.
    /// Browser WebAssembly uses the separate byte-fed Sceptre worker API.
    backend: []const u8,
    /// Language code(s) for OCR recognition. Defaults to `["eng"]`. For Tesseract,
    /// languages are joined with "+".
    ///
    /// A list is the canonical form and the only form accepted by the binding
    /// object APIs (Python, Node, PHP, WASM, etc.): `["eng", "deu"]`. When
    /// deserializing from a config file, JSON body, or the REST/MCP API, a
    /// single string is also accepted, either as one code ("eng") or
    /// "+"-joined ("eng+deu").
    ///
    /// The four candle-based backends also use this list to decide which scripts are
    /// plausible in their output, dropping a line written in an unconfigured script.
    language: []const []const u8,
    /// Output format for OCR results (optional, for format conversion)
    output_format: ?OutputFormat = null,
    /// Legacy PaddleOCR configuration JSON.
    ///
    /// Deprecated since 1.3.2 and planned for removal in 2.0. Use
    /// `Self.paddle_ocr_settings` for typed access.
    paddle_ocr_config: ?[]const u8 = null,
    /// Typed PaddleOCR-specific configuration (optional).
    ///
    /// Any `PaddleOcrConfig` field can be set here; unset fields keep their defaults. In a config
    /// file, a JSON config, or a REST or MCP request body, an unknown key is a configuration error.
    /// A typed object built in a binding has only the fields it declares, so it ignores any other
    /// property, as every other typed config does. The most common overrides are `model_version`
    /// (`"pp-ocrv6"` default / `"pp-ocrv5"`) and `model_tier`. In TOML:
    ///
    /// ```toml
    /// [ocr.paddle_ocr_settings]
    /// model_version = "pp-ocrv5"
    /// model_tier = "server"
    /// ```
    ///
    /// The `XBERG_OCR_MODEL_VERSION` / `XBERG_OCR_MODEL_TIER` environment variables set the same two
    /// keys for env-configured servers (issue #1279).
    paddle_ocr_settings: ?PaddleOcrConfig = null,
    /// Arbitrary per-call options passed through to the backend unchanged.
    ///
    /// Custom OCR backends and built-in backends that support runtime tuning
    /// can read this value and deserialize the keys they care about. Keys
    /// unknown to the backend are silently ignored.
    ///
    /// This is the recommended extension point for per-call parameters that
    /// are not covered by the typed fields above (e.g. mode switching,
    /// preprocessing flags, inference batch size).
    ///
    /// **Scope:** when `pipeline` is `null`, this value is propagated to the
    /// primary stage of the auto-constructed pipeline. When `pipeline` is
    /// explicitly set, this field has **no effect** — the caller must set
    /// `OcrPipelineStage.backend_options` directly on the relevant stage(s)
    /// instead.
    ///
    /// Example:
    /// ```json
    /// { "mode": "fast", "enable_layout": true, "timeout_ms": 5000 }
    /// ```
    backend_options: ?[]const u8 = null,
    /// OCR element extraction configuration
    element_config: ?OcrElementConfig = null,
    /// Quality thresholds for the native-text-to-OCR fallback decision.
    /// When None, uses compiled defaults (matching previous hardcoded behavior).
    quality_thresholds: ?OcrQualityThresholds = null,
    /// Multi-backend OCR pipeline configuration. When set, enables weighted
    /// fallback across multiple OCR backends based on output quality.
    /// When None, uses the single `backend` field (same as today).
    pipeline: ?OcrPipelineConfig = null,
    /// Page rotation policy based on orientation detection.
    ///
    /// - `Some(true)`: always detect the page orientation (0/90/180/270 degrees) with an
    ///   ONNX PP-LCNet document-orientation classifier -- NOT Tesseract's own
    ///   `DetectOrientationScript()`/OSD, which this library does not call -- and correct a
    ///   confidently rotated page before recognition. Applies to every OCR backend; the
    ///   tesseract-only `TesseractConfig.preprocessing` field of the same name is OR'd in on
    ///   top of this one and affects tesseract alone.
    ///
    /// - `Some(false)`: never rotate and never run the orientation retry.
    /// - `null` (omitted): the default. Pages are read as-is, and a low-confidence whole-page
    ///   read of a plain Tesseract block is retried with the orientation recovery that
    ///   extraction without an `ocr` block uses (cached OSD when present, the ONNX classifier
    ///   otherwise).
    ///
    /// Independent of a page's PDF `/Rotate` entry, which is handled separately
    /// on every OCR route regardless of this setting.
    auto_rotate: ?bool = null,
    /// Ergonomic VLM fallback policy.
    ///
    /// When set to anything other than `VlmFallbackPolicy.Disabled` and
    /// `OcrConfig.pipeline` is `null`, a multi-stage pipeline is synthesised
    /// automatically:
    ///
    /// - `VlmFallbackPolicy.OnLowQuality` → `[classical_stage, vlm_stage]` with the
    ///   `quality_threshold` mapped onto `OcrQualityThresholds.pipeline_min_quality`.
    ///
    /// - `VlmFallbackPolicy.Always` → `[vlm_stage]` only.
    ///
    /// Requires `OcrConfig.vlm_config` to be `Some` when not `Disabled`.
    /// When `OcrConfig.pipeline` is explicitly set, this field is ignored.
    vlm_fallback: VlmFallbackPolicy = .disabled,
    /// VLM (Vision Language Model) OCR configuration.
    ///
    /// Required when `backend` is `"vlm"` or when `vlm_fallback` is not
    /// `VlmFallbackPolicy.Disabled`. Uses liter-llm to send page images to a
    /// vision model for text extraction.
    vlm_config: ?LlmConfig = null,
    /// Custom Jinja2 prompt template for VLM OCR.
    ///
    /// When `null`, uses the default template. Available variables:
    ///
    /// - `{{ language }}` — The document language code (e.g., "eng", "deu").
    vlm_prompt: ?[]const u8 = null,
    /// Hardware acceleration for ONNX Runtime models (e.g. PaddleOCR, layout detection).
    ///
    /// Not user-configurable via config files — injected at runtime from
    /// `ExtractionConfig.acceleration` before each `process_image` call.
    acceleration: ?AccelerationConfig = null,
    /// Security limits applied when decoding raw image bytes for OCR (GH#1554).
    ///
    /// Not user-configurable via config files — injected at runtime from
    /// `ExtractionConfig.security_limits` before each `process_image` call, the same
    /// pattern `Self.acceleration` uses. `ExtractionConfig.security_limits` remains the
    /// source of truth and overwrites this field whenever it carries a value; a value set
    /// here directly is honoured only when `ExtractionConfig` carries none, so the two
    /// cannot drift while a directly-set limit is no longer silently discarded (GH#1651).
    /// A backend consulting a
    /// `backend_options` override for this call may still let that override win, but in
    /// the absence of one this field is what backends should fall back to instead of
    /// `SecurityLimits.default()`. `null` means "use `SecurityLimits.default()`", never
    /// "disable the check".
    security_limits: ?SecurityLimits = null,
    /// Caller-supplied Tesseract `traineddata` bytes per language code.
    ///
    /// Primary use case is the WASM build, which has no filesystem and cannot
    /// download tessdata at runtime. Native builds typically rely on
    /// `TessdataManager` and ignore this field. When present, the WASM
    /// Tesseract backend prefers these bytes over its compile-time-bundled
    /// English data.
    ///
    /// Skipped by serde to keep config files small — supply via the typed API
    /// at runtime.
    tessdata_bytes: ?std.StringHashMap([]const u8) = null,
    /// Runtime override for tessdata directory path.
    ///
    /// When set, uses this path as the highest-priority tessdata location,
    /// bypassing environment variables and cache directories. Useful for
    /// embedding pre-installed tessdata in applications. When `null`, uses
    /// the standard resolution chain: TESSDATA_PREFIX env, cache dir, system paths.
    tessdata_path: ?[]const u8 = null,
    /// Repair OCR tokens that are clearly numeric but mis-punctuated: a dropped thousands
    /// separator, a decimal point misread for a grouping comma, or one number split into two
    /// tokens at a rendering gap (GH#1789).
    ///
    /// Defaults to `false`. Unlike the always-on list-marker repair
    /// (`crate.extractors.pdf.ocr.scoring.repair_ocr_list_markers`), this repair has no
    /// table-column context available at the point OCR text comes back as a flat string, so it
    /// cannot tell `"1.234,56"` (European) from `"1,234.56"` (US) apart on its own -- it always
    /// assumes the US/UK convention (comma groups, period decimals).
    ///
    /// The rules read only the punctuation and digit counts, never whether a token is an amount,
    /// so each of these is rewritten too (GH#1836). Enable it only for documents whose numbers are
    /// amounts, and which use that convention:
    ///
    /// - A bare 4-9 digit integer becomes grouped, whatever it denotes: `"Year 2019"` ->
    ///   `"Year 2,019"`, and likewise a ZIP code, a page number or a part number. Only a literal
    ///   `"FY "` prefix is exempt.
    ///
    /// - A US-convention decimal with exactly three fraction digits and at most three integer
    ///   digits becomes an amount: `"0.125"` -> `"0,125"`. Four fraction digits (`"0.7906"`) or a
    ///   trailing `%` are left alone.
    ///
    /// - A lone digit followed by a single space and an already-grouped number is joined, which is
    ///   indistinguishable from two adjacent table cells: `"5 12,000"` -> `"512,000"`.
    ///
    /// The repair is skipped entirely when `tesseract_config.output_format` is `"hocr"` or
    /// `"tsv"`, because it would re-punctuate the bare coordinate integers in that markup.
    numeric_repair: bool,
};

/// A unified OCR element representing detected text with full metadata.
///
/// This is the primary type for structured OCR output, preserving all information
/// from both Tesseract and PaddleOCR backends.
pub const OcrElement = struct {
    /// The recognized text content.
    text: []const u8,
    /// Bounding geometry (rectangle or quadrilateral).
    geometry: OcrBoundingGeometry,
    /// Confidence scores for detection and recognition.
    confidence: OcrConfidence,
    /// Hierarchical level (word, line, block, page).
    level: OcrElementLevel = .line,
    /// Rotation information (if detected).
    rotation: ?OcrRotation = null,
    /// Page number (1-indexed).
    page_number: u32,
    /// Parent element ID for hierarchical relationships.
    ///
    /// When hierarchy output is enabled, this resolves to another emitted element's
    /// `backend_metadata["element_id"]` value.
    parent_id: ?[]const u8 = null,
    /// Backend-specific metadata that doesn't fit the unified schema.
    backend_metadata: std.StringHashMap([]const u8),
};

/// Configuration for OCR element extraction.
///
/// Controls how OCR elements are extracted and filtered.
pub const OcrElementConfig = struct {
    /// Whether to include OCR elements in the extraction result.
    ///
    /// When true, the `ocr_elements` field in `ExtractedDocument` will be populated.
    include_elements: bool,
    /// Minimum hierarchical level to include.
    ///
    /// Elements below this level (e.g., words when min_level is Line) will be excluded.
    min_level: OcrElementLevel = .line,
    /// Minimum recognition confidence threshold (0.0-1.0).
    ///
    /// Elements with confidence below this threshold will be filtered out.
    min_confidence: f64,
    /// Whether to build hierarchical relationships between elements.
    ///
    /// When true, emitted elements receive an `element_id` metadata value and `parent_id`
    /// references are populated only when a spatially containing parent is also emitted.
    build_hierarchy: bool,
};

/// OCR processing metadata.
///
/// Captures information about OCR processing configuration and results.
pub const OcrMetadata = struct {
    /// OCR language code(s) used
    language: []const u8,
    /// Tesseract Page Segmentation Mode (PSM)
    psm: i32,
    /// Output format (e.g., "text", "hocr")
    output_format: []const u8,
    /// Number of tables detected
    table_count: u32,
    /// Number of rows in the detected table (if a single table was found).
    table_rows: ?u32 = null,
    /// Number of columns in the detected table (if a single table was found).
    table_cols: ?u32 = null,
};

/// A page whose OCR failed while extraction of the document continued.
///
/// The warning in `ExtractedDocument.processing_warnings` stays available. One warning
/// can cover several pages: when an automatic OCR run of selected pages fails as a whole,
/// it adds one warning and one record for each selected page. When the OCR fallback for the
/// whole document fails, it adds one warning and one record for each page that has no native
/// text. Repeated failures on one page make one record.
pub const OcrPageFailure = struct {
    /// One-based page number in the source document.
    page: u32,
    /// OCR backend error text.
    error_: []const u8,
    /// Whether content for this page was retained or recovered through another route.
    recovered: bool,
};

/// Multi-backend OCR pipeline with quality-based fallback.
///
/// Backends are tried in priority order (highest first). After each backend
/// produces output, quality is evaluated. If it meets `quality_thresholds.pipeline_min_quality`,
/// the result is accepted. Otherwise the next backend is tried; if none clears the
/// threshold, an internal selection policy derived from the `OcrConfig` decides which
/// stage's result is returned as the best effort (`vlm_fallback` pipelines prefer their
/// last non-empty stage; explicit and classical pipelines stay score-based).
pub const OcrPipelineConfig = struct {
    /// Ordered list of backends to try. Sorted by priority (descending) at runtime.
    stages: []const OcrPipelineStage,
    /// Quality thresholds for deciding whether to accept a result or try the next backend.
    quality_thresholds: OcrQualityThresholds,
};

/// A single backend stage in the OCR pipeline.
pub const OcrPipelineStage = struct {
    /// Backend name: "tesseract", "paddleocr", "paddle-ocr", "sceptre", "vlm", or a custom registered name.
    /// Sceptre uses ONNX Runtime on desktop/server and tract on Android/iOS; browser WebAssembly has a separate
    /// byte-fed engine because the normal async OCR registry assumes native model storage.
    backend: []const u8,
    /// Priority weight (higher = tried first). Stages are sorted by priority descending.
    priority: u32,
    /// Language override for this stage (None = use parent OcrConfig.language).
    ///
    /// A list is the canonical form and the only form accepted by the binding
    /// object APIs: `["eng", "deu"]`. When deserializing from a config file,
    /// JSON body, or the REST/MCP API, a single string is also accepted,
    /// either as one code ("eng") or "+"-joined ("eng+deu").
    language: ?[]const []const u8 = null,
    /// Legacy PaddleOCR config JSON for this stage.
    ///
    /// Deprecated since 1.3.2 and planned for removal in 2.0. Use
    /// `Self.paddle_ocr_settings` for typed access.
    paddle_ocr_config: ?[]const u8 = null,
    /// Typed PaddleOCR config for this stage.
    ///
    /// When both PaddleOCR fields are set, this typed field takes precedence.
    paddle_ocr_settings: ?PaddleOcrConfig = null,
    /// VLM config override for this pipeline stage.
    vlm_config: ?LlmConfig = null,
    /// Arbitrary per-call options passed through to the backend unchanged.
    ///
    /// Backends that support runtime tuning (mode switching, preprocessing
    /// flags, inference parameters, etc.) read this value and deserialize
    /// the keys they care about. Keys unknown to the backend are silently
    /// ignored, so options from different backends can coexist in the same
    /// config without conflict.
    ///
    /// Example (custom backend):
    /// ```json
    /// { "mode": "fast", "enable_layout": true }
    /// ```
    backend_options: ?[]const u8 = null,
};

/// A point in OCR raster pixel coordinates.
pub const OcrPoint = struct {
    /// Horizontal coordinate.
    x: u32,
    /// Vertical coordinate.
    y: u32,
};

/// Quality thresholds for OCR fallback decisions and pipeline quality gating.
///
/// Fields default to conservative extraction behavior. Suspected OCR recognition noise is
/// reported but retained unless destructive filtering is explicitly enabled.
pub const OcrQualityThresholds = struct {
    /// Minimum total non-whitespace characters to consider text substantive.
    min_total_non_whitespace: u64,
    /// Minimum non-whitespace characters per page on average.
    min_non_whitespace_per_page: f64,
    /// Minimum character count for a word to be "meaningful".
    min_meaningful_word_len: u64,
    /// Minimum count of meaningful words before text is accepted.
    min_meaningful_words: u64,
    /// Minimum alphanumeric ratio (non-whitespace chars that are alphanumeric).
    min_alnum_ratio: f64,
    /// Minimum Unicode replacement characters (U+FFFD) to trigger OCR fallback.
    min_garbage_chars: u64,
    /// Maximum fraction of short (1-2 char) words before text is considered fragmented.
    max_fragmented_word_ratio: f64,
    /// Critical fragmentation threshold — triggers OCR regardless of meaningful words.
    /// Normal English text has ~20-30% short words. 80%+ is definitive garbage.
    critical_fragmented_word_ratio: f64,
    /// Maximum fraction of short (1-2 char) words an *OCR result* may carry before the page
    /// is reported as suspected recognition noise.
    ///
    /// This is a different decision, and a different operating point, from
    /// `Self.max_fragmented_word_ratio` / `Self.critical_fragmented_word_ratio`: those
    /// ask "is the native text bad enough that we should OCR this page?", and are tuned to
    /// only fire on text that is already definitively broken (0.6 / 0.8). Here we are judging
    /// what OCR *produced*, where the failure mode is an engine run over line art — a scanned
    /// plat, an engineering drawing, a signature flourish — returning confident-looking
    /// strings that are not words.
    ///
    /// Measured over the 16 pages of a recorded municipal ordinance (13 prose pages, 3 scanned
    /// survey drawings): prose ran 0.04-0.28, the drawings 0.42-0.47. The default sits in that
    /// gap with margin on both sides. By default, crossing the threshold emits a processing
    /// warning and retains the recognized text, except for the symbol-noise lines that
    /// `Self.prune_symbol_noise_lines` removes. Set `Self.discard_suspected_ocr_noise` to
    /// `true` to restore destructive filtering of the whole page.
    max_ocr_output_fragmented_word_ratio: f64,
    /// Minimum mean OCR confidence (0-100) below which a page is reported as suspected noise.
    ///
    /// This is the engine's own uncertainty about what it read, and it is a far sharper
    /// instrument than any statistic derived from the output text. Measured per page over a
    /// recorded municipal ordinance (10 prose pages, 6 scanned survey/architectural drawings)
    /// with Tesseract 5.5.3:
    ///
    /// ```text
    /// prose      86.3 - 95.3
    /// drawings   18.5 - 64.3
    /// ```
    ///
    /// The default sits in that gap with ~11 points of margin on each side. Compare the
    /// short-word ratio, which separated the same two groups by 0.09 on a 0-1 scale.
    ///
    /// A backend that reports no confidence (no `mean_text_conf` in its result metadata)
    /// skips this check entirely and falls back to
    /// `Self.max_ocr_output_fragmented_word_ratio`. By default, the signal emits a warning
    /// without discarding content. Set to 0.0 to disable the signal.
    min_ocr_mean_confidence: f64,
    /// Minimum word count before `Self.max_ocr_output_fragmented_word_ratio` may report a
    /// page. Short pages (a signature block, an exhibit title) are legitimately dominated by
    /// short words, so the ratio is not meaningful on them and the signal stays disabled.
    min_words_for_ocr_output_check: u64,
    /// Maximum fraction of a Tesseract page's dictionary-checkable words that
    /// `TesseractAPI.is_valid_word` may reject before the page is treated as recognition
    /// noise, supplementing (never replacing) `Self.max_ocr_output_fragmented_word_ratio`.
    ///
    /// Tesseract-only: other backends never report this ratio (see
    /// `dictionary_invalid_word_ratio` in `ocr.processor.execution`), so this threshold is
    /// simply never consulted for them.
    ///
    /// Calibration owed, same as `ocr.types.TesseractConfig.min_confidence`:
    /// unlike `Self.max_ocr_output_fragmented_word_ratio` (measured across a recorded
    /// ordinance's prose vs. drawing pages), this ratio has not yet had a page-level
    /// measurement run over a labeled corpus. The default therefore disables the check
    /// entirely (`1.01`, above the `[0.0, 1.0]` range a ratio can reach) rather than guess an
    /// operating point. Do not lower this without running that measurement first.
    max_ocr_output_dict_invalid_word_ratio: f64,
    /// Discard non-empty OCR text when any configured recognition-noise signal fires.
    ///
    /// Defaults to `false`: suspected noise is retained and surfaced through
    /// `processing_warnings`, minus the symbol-noise lines `Self.prune_symbol_noise_lines`
    /// removes. Set to `true` to preserve the legacy destructive behavior.
    discard_suspected_ocr_noise: bool,
    /// Remove symbol-noise lines from a page flagged as suspected recognition noise but retained.
    ///
    /// Applies to any such page, not only photographs, when it has at least 8 non-blank lines
    /// and at least half of them are symbol noise. A lone capitalized 3-letter token (`Tee`) is
    /// pruned from such a page but does not count toward that half. A line is kept when it reads
    /// as text and is pruned only when it is made of symbols and fragments:
    ///
    /// - a line with a digit is kept, unless every token that holds a digit pairs it with a
    ///   stray quotation mark or a trailing section mark (`"9`, `5§`) and no other token is
    ///   plausible text; a closed quote (`"9"`, `‘9’`), `§12` and `"5 items` stay;
    ///
    /// - a line with a character of a script written without spaces (CJK ideographs, Kana,
    ///   Hangul, Thai, Lao, Khmer, Myanmar) or a token with a letter outside the Latin script
    ///   (Arabic, Cyrillic, Greek, ...) is kept;
    ///
    /// - an equation or assignment is kept, spaced or not: an `=`, `+`, `<`, `>` or
    ///   comparison/multiplication sign with operands (a word of 3 or more letters, one letter
    ///   other than `i`, `l`, `j`, `o`, or a call such as `f(x)`) on its sides (`x = y`, `X= Y`,
    ///   `x=y`, `a=`, `f(x) = x`); `oe = ie` and `i - l` are pruned;
    ///
    /// - a single token is kept when it has 4 or more letters, is a contraction, is a run of
    ///   consecutive letters (`ABC`, `pqr`), is a capitalized word of 2 or 3 letters ending in a
    ///   full stop, `!` or `?` (`No.`, `Yes.`), or is a capitalized 3-letter word with a letter
    ///   outside ASCII (`Été`); `mal`, `Ne`, `Tee`, `CAS` and `a` are pruned;
    ///
    /// - a line of several tokens is kept when at least two tokens and at least half of the
    ///   line are word-like (`Annual report q z`). Latin words need 3 letters and may contain
    ///   an apostrophe, hyphen or dot. Contractions, non-Latin word shapes, and short function
    ///   words also qualify (`Go to q z`). A line needs a word-shaped token or a function word
    ///   with at least two letters. `were ee` and tokens split by stray symbols fail this rule;
    ///
    /// - a line of several tokens is also kept when at least two thirds of its tokens are plausible
    ///   text and it holds a word of 3 or more letters or two function words (`Go to Al`,
    ///   `b) to go`, `Mr X Is In`, `de la gare`, `Mairie du I`). A token is plausible text when it
    ///   is a word of 3 or more letters, an English or common Romance/German function word, a
    ///   capitalized initial or abbreviation of 1 or 2 letters, a list label such as `b)`, or a
    ///   contraction; `ee so`, `we SY` and `a a` are pruned. Two lowercase 3-letter tokens
    ///   together count as plausible, so `mal cad` is kept while a lone `mal` is pruned.
    ///
    /// A page that is mostly photograph noise keeps the capitalized fragments and digit-bearing
    /// lines that read as text, so pruning shrinks the noise rather than clearing it.
    ///
    /// Pages with tables and pages discarded by `Self.discard_suspected_ocr_noise` are not
    /// pruned. Stage scoring in a multi-stage OCR pipeline and the single-page first-pass
    /// quality gate read the text before pruning. Each pruned page adds a processing warning
    /// naming the page and the number of lines removed. Set to `false` to keep every
    /// recognized line.
    prune_symbol_noise_lines: bool,
    /// Minimum average word length. Below this with enough words indicates garbled extraction.
    min_avg_word_length: f64,
    /// Minimum word count before average word length check applies.
    min_words_for_avg_length_check: u64,
    /// Minimum consecutive word repetition ratio to detect column scrambling.
    min_consecutive_repeat_ratio: f64,
    /// Minimum word count before consecutive repetition check is applied.
    min_words_for_repeat_check: u64,
    /// Minimum character count for "substantive markdown" OCR skip gate.
    substantive_min_chars: u64,
    /// Minimum character count for "non-text content" OCR skip gate.
    non_text_min_chars: u64,
    /// Alphanumeric+whitespace ratio threshold for skip decisions.
    alnum_ws_ratio_threshold: f64,
    /// Minimum quality score (0.0-1.0) for a pipeline stage result to be accepted.
    /// If the result from a backend scores below this, try the next backend.
    pipeline_min_quality: f64,
    /// Minimum fraction of non-whitespace characters that are undecodable
    /// (Unicode Private Use Area, replacement characters, or non-whitespace
    /// control characters) before a page's text layer is treated as
    /// unreadable and routed to OCR (issue #1254). Gated by
    /// `min_total_non_whitespace` so short snippets with a stray symbol or
    /// two do not trip this check.
    min_undecodable_ratio: f64,
    /// Whether to route a page to OCR when xberg_native_pdf reports that a high
    /// fraction of its text was fabricated rather than read from the file
    /// (`MappingProvenance.Fallback`, xberg_native_pdf 0.3.75+, issue #1254). This is
    /// a direct fact from the extractor's ISO 32000-1 §9.10.2 mapping cascade,
    /// distinct from the character-heuristic proxy behind `min_undecodable_ratio`.
    /// Defaults to `true`.
    enable_provenance_ocr_routing: bool,
    /// Minimum fraction of a page's non-whitespace characters with
    /// `MappingProvenance.Fallback` provenance before the page is treated as
    /// having a fabricated text layer and routed to OCR (issue #1254). Gated by
    /// `min_total_non_whitespace` so a short page with a stray fallback
    /// character cannot trip it. Only used when `enable_provenance_ocr_routing`
    /// is `true`.
    min_provenance_fallback_ratio: f64,
    /// Whether to route a page to OCR when its decoded text does not read as any real,
    /// detectable language (issue #1696). Unlike `enable_provenance_ocr_routing`, this
    /// catches a `/ToUnicode` CMap that resolves every glyph to *a* character, but
    /// consistently the WRONG one (e.g. a ROT-shifted mapping) -- text that is structurally
    /// indistinguishable from real prose to every character-shape check, including the
    /// provenance signal, because the mapping tier really is file-backed. Defaults to `true`.
    enable_plausibility_ocr_routing: bool,
    /// Minimum fraction of a page's language-detection chunks that whatlang classifies as
    /// reliable (`Info.is_reliable()`) before the page is trusted as legible (issue #1696).
    /// Below this AND below the mean-confidence guard together, the page's text layer is
    /// treated as implausible and routed to OCR. Only used when
    /// `enable_plausibility_ocr_routing` is `true`.
    min_reliable_language_chunk_ratio: f64,
};

/// Rotation information for an OCR element.
pub const OcrRotation = struct {
    /// Rotation angle in degrees (0, 90, 180, 270 for PaddleOCR).
    angle_degrees: f64,
    /// Confidence score for the rotation detection.
    confidence: ?f64 = null,
};

/// Configuration for PaddleOCR backend.
///
/// Configures PaddleOCR text detection and recognition with multi-language support.
/// Uses a builder pattern for convenient configuration.
pub const PaddleOcrConfig = struct {
    /// Language code (e.g., "en", "ch", "jpn", "kor", "deu", "fra")
    language: []const u8,
    /// Optional Hugging Face Hub cache root for model files.
    ///
    /// When unset, `XBERG_OCR_MODEL_CACHE_DIR` is used when non-empty, followed by the standard
    /// `HF_HUB_CACHE`, legacy `HUGGINGFACE_HUB_CACHE`, and `HF_HOME` conventions.
    cache_dir: ?[]const u8 = null,
    /// Enable angle classification for rotated text (default: false).
    /// Can misfire on short text regions, rotating crops incorrectly before recognition.
    use_angle_cls: bool,
    /// Enable table structure detection (default: **false**, unlike `TesseractConfig`
    /// which defaults to `true` — see `crate.ocr.types.TesseractConfig`).
    ///
    /// PaddleOCR has no per-word table-candidate confidence carve-out the way Tesseract's
    /// TSV does (every recognised word is a clustering candidate), so unfiltered clustering
    /// over-fabricates tables on ordinary prose. This stays off until it clears a
    /// cell-scored accuracy measurement (see the pinning test at the bottom of this file).
    /// Consequence for callers: switching an existing config from the Tesseract backend to
    /// PaddleOCR with stock defaults silently produces **no** OCR tables — enable this
    /// explicitly if you need them.
    ///
    /// When enabled, this only clusters and reconstructs a grid from word boxes PaddleOCR
    /// has already produced (see `crate.paddle_ocr.backend.PaddleOcrBackend.process_image`)
    /// — it does not run any additional model inference, so the added per-page cost is the
    /// CPU-only clustering/reconstruction pass, not another ONNX call.
    enable_table_detection: bool,
    /// Database threshold for text detection (default: 0.3)
    /// Range: 0.0-1.0, higher values require more confident detections
    det_db_thresh: f32,
    /// Box threshold for text bounding box refinement (default: 0.5)
    /// Range: 0.0-1.0
    det_db_box_thresh: f32,
    /// Unclip ratio for expanding text bounding boxes (default: 1.6)
    /// Controls the expansion of detected text regions
    det_db_unclip_ratio: f32,
    /// Maximum side length for detection image (default: 1024)
    /// Larger images may be resized to this limit for faster inference
    det_limit_side_len: u32,
    /// Batch size for recognition inference (default: 6)
    /// Number of text regions to process simultaneously
    rec_batch_num: u32,
    /// Padding in pixels added around the image before detection (default: 10).
    /// Large values can include surrounding content like table gridlines.
    padding: u32,
    /// Minimum recognition confidence score for text lines (default: 0.5).
    /// Text regions with recognition confidence below this threshold are discarded.
    /// Matches PaddleOCR Python's `drop_score` parameter.
    /// Range: 0.0-1.0
    drop_score: f32,
    /// Model tier controlling detection/recognition model size and accuracy trade-off.
    ///
    /// For PP-OCRv5 (`model_version = "pp-ocrv5"`):
    ///
    /// - `"mobile"` (default): Lightweight models (~4.5MB detection, ~16.5MB recognition), fast download and inference
    /// - `"server"`: Large, high-accuracy models (~88MB detection, ~84MB recognition), best for GPU or complex documents
    ///
    /// For PP-OCRv6 (`model_version = "pp-ocrv6"`, the default):
    ///
    /// - `"small"`: ~9.9MB detection, full 18,708-char CJK+Latin+JA/KO recognition dictionary.
    ///   The default `"mobile"` resolves here, so this is what an unconfigured extraction uses.
    ///
    /// - `"medium"`: ~62MB detection, same dictionary. Higher accuracy, substantially slower on
    ///   CPU. A legacy `"server"` tier, or any unrecognised value, resolves here.
    ///
    /// - `"tiny"`: ~1.8MB detection, but a reduced 6,904-char (~zh/en) dictionary — it cannot
    ///   read the scripts the other two cover.
    ///
    /// Note PaddleOCR pages do not run concurrently: the ONNX session is held behind a mutex, so
    /// the thread budget goes to intra-op parallelism and wall time scales with page count times
    /// per-page inference. Tier choice therefore dominates throughput on multi-page documents.
    model_tier: []const u8,
    /// Model generation: `"pp-ocrv6"` (default) or `"pp-ocrv5"`.
    ///
    /// PP-OCRv6 adds a unified CJK+Latin+JA/KO recognition model with `medium`/`small`/`tiny`
    /// tiers (see `model_tier`). Scripts outside the v6 unified coverage (Arabic, Cyrillic,
    /// Devanagari, Greek, Tamil, Telugu, Thai) transparently fall back to the PP-OCRv5
    /// per-script recognition models. Defaults to `"pp-ocrv6"`; the default `model_tier`
    /// (`"mobile"`) resolves to the v6 `"small"` tier. Select `"pp-ocrv5"` to pin the
    /// legacy per-script/unified fleet.
    model_version: []const u8,
    /// Explicit inference engine choice.
    ///
    /// `null` (the default) resolves to the compiled default: `ort` when the
    /// `paddle-ocr-ort` feature is compiled in, otherwise `tract`. An explicit choice
    /// is validated against the compiled features when the OCR engine is constructed
    /// (see `crate.paddle_ocr.backend.effective_backend`); requesting an engine
    /// whose feature is not compiled in is a clear configuration error rather than a
    /// silent fallback.
    inference_backend: ?PaddleInferenceBackend = null,
};

/// Byte offset boundary for a page.
///
/// Tracks where a specific page's content starts and ends in the main content string,
/// enabling mapping from byte positions to page numbers. Offsets are guaranteed to be
/// at valid UTF-8 character boundaries when using standard String methods (push_str, push, etc.).
pub const PageBoundary = struct {
    /// Byte offset where this page starts in the content string (UTF-8 valid boundary, inclusive)
    byte_start: u64,
    /// Byte offset where this page ends in the content string (UTF-8 valid boundary, exclusive)
    byte_end: u64,
    /// Page number (1-indexed)
    page_number: u32,
};

/// Classification result for a single page.
pub const PageClassification = struct {
    /// 1-indexed page number this classification belongs to.
    page_number: u32,
    /// Labels assigned to the page. Single-label classification yields exactly one
    /// entry; multi-label classification yields any subset of the configured label set.
    labels: []const ClassificationLabel,
};

/// Configuration for the page-classification post-processor.
pub const PageClassificationConfig = struct {
    /// Minijinja prompt template. Receives `{{ labels }}` (joined list), `{{ page_text }}`
    /// and `{{ multi_label }}` variables. `null` lets the backend pick a sensible default.
    prompt_template: ?[]const u8 = null,
    /// The set of labels the classifier may emit. Must contain at least one entry.
    labels: []const []const u8,
    /// Allow multiple labels per page. Single-label mode returns at most one label.
    multi_label: bool,
    /// LLM configuration used for classification.
    llm: LlmConfig,
};

/// Page extraction and tracking configuration.
///
/// Controls how pages are extracted, tracked, and represented in the extraction results.
/// When `null`, page tracking is disabled.
///
/// Page range tracking in chunk metadata (first_page/last_page) is automatically enabled
/// when page boundaries are available and chunking is configured.
pub const PageConfig = struct {
    /// Extract pages as separate array (ExtractedDocument.pages)
    extract_pages: bool,
    /// Insert page markers in main content string
    insert_page_markers: bool,
    /// Page marker format (use {page_num} placeholder)
    /// Default: "\n\n<!-- PAGE {page_num} -->\n\n"
    marker_format: []const u8,
    /// Keep the text layer of a PDF page whose `content` OCR output replaces, for a caller that needs the exact
    /// characters of a short born-digital page. The text layer is returned in `PageContent.native_content`.
    /// Needs `extract_pages`.
    keep_native_content: bool,
};

/// Content for a single page/slide.
///
/// When page extraction is enabled, documents are split into per-page content
/// with associated tables and images mapped to each page.
///
/// # Performance
///
/// Uses shared tables and images for memory efficiency:
///
/// - `[]const Table` enables zero-copy sharing of table data
/// - `[]const ExtractedImage` enables zero-copy sharing of image data
/// - Maintains exact JSON compatibility via custom Serialize/Deserialize
///
/// This reduces memory overhead for documents with shared tables/images
/// by avoiding redundant copies during serialization.
pub const PageContent = struct {
    /// Page number (1-indexed)
    page_number: u32,
    /// Text content for this page
    content: []const u8,
    /// Tables found on this page (uses Arc for memory efficiency)
    ///
    /// Serializes as `[]const Table` for JSON compatibility while maintaining
    /// shared in-memory ownership for zero-copy sharing.
    tables: []const Table,
    /// Indices into `ExtractedDocument.images` for images found on this page.
    ///
    /// Each value is a zero-based index into the top-level `images` collection.
    /// Only populated when `extract_images = true` in the extraction config.
    image_indices: []const u32,
    /// OCR image preprocessing applied to this page's raster.
    image_preprocessing: ?ImagePreprocessingMetadata = null,
    /// Hierarchy information for the page (when hierarchy extraction is enabled)
    ///
    /// Contains text hierarchy levels (H1-H6) extracted from the page content.
    hierarchy: ?PageHierarchy = null,
    /// Whether this page is blank (no meaningful text content)
    ///
    /// Determined during extraction based on text content analysis.
    /// A page is blank if it has fewer than 3 non-whitespace characters
    /// and contains no tables or images.
    is_blank: ?bool = null,
    /// Layout detection regions for this page (when layout detection is enabled).
    ///
    /// Contains detected layout regions with class, confidence, bounding box,
    /// and area fraction. Only populated when layout detection is configured.
    layout_regions: ?[]const LayoutRegion = null,
    /// Speaker notes for this slide (PPTX only).
    ///
    /// Contains the text from the slide's notes pane (`ppt/notesSlides/notesSlide{N}.xml`).
    /// Only populated when the source is a PPTX file and notes are present.
    speaker_notes: ?[]const u8 = null,
    /// Section name this slide belongs to (PPTX only).
    ///
    /// PowerPoint sections group slides into logical chapters (`<p:sectionLst>` in
    /// `ppt/presentation.xml`). Only populated when the source is a PPTX file and
    /// the slide belongs to a named section.
    section_name: ?[]const u8 = null,
    /// Sheet name for this page (XLSX/ODS only).
    ///
    /// Each spreadsheet sheet maps to one `PageContent` entry. This field carries the
    /// sheet's display name as it appears in the workbook. `null` for all non-spreadsheet
    /// formats and for sheets with an empty name.
    sheet_name: ?[]const u8 = null,
    /// Aggregate OCR confidence for this page. `null` when the page was not OCR'd.
    ocr_confidence: ?PageOcrConfidence = null,
    /// Text layer of this page, kept when OCR output replaced it in `content`.
    ///
    /// Set only when `PageConfig.keep_native_content` is on, an OCR route replaced this page's `content`, and the
    /// text layer is not blank and differs from the OCR text. `null` on every other page. PDF only.
    native_content: ?[]const u8 = null,
};

/// Metadata for individual page/slide/sheet.
///
/// Captures per-page information including dimensions, content counts,
/// and visibility state (for presentations).
pub const PageDimensions = struct {
    /// Page width in points or pixels.
    width: f64,
    /// Page height in points or pixels.
    height: f64,
};

/// Page hierarchy structure containing heading levels and block information.
///
/// Used when PDF text hierarchy extraction is enabled. Contains hierarchical
/// blocks with heading levels (H1-H6) for semantic document structure.
pub const PageHierarchy = struct {
    /// Number of hierarchy blocks on this page
    block_count: u32,
    /// Hierarchical blocks with heading levels
    blocks: []const HierarchicalBlock,
};

pub const PageInfo = struct {
    /// Page number (1-indexed)
    number: u32,
    /// Page title (usually for presentations)
    title: ?[]const u8 = null,
    /// Dimensions in points (PDF) or pixels (images).
    dimensions: ?PageDimensions = null,
    /// Number of images on this page
    image_count: ?u32 = null,
    /// Number of tables on this page
    table_count: ?u32 = null,
    /// Whether this page is hidden (e.g., in presentations)
    hidden: ?bool = null,
    /// Whether this page is blank (no meaningful text, no images, no tables)
    ///
    /// A page is considered blank if it has fewer than 3 non-whitespace characters
    /// and contains no tables or images. This is useful for filtering out empty pages
    /// in scanned documents or PDFs with blank separator pages.
    is_blank: ?bool = null,
    /// Whether this page contains non-trivial vector graphics (paths, shapes, curves)
    ///
    /// Indicates the presence of vector-drawn content such as charts, diagrams,
    /// or geometric shapes (e.g., from Adobe InDesign, LaTeX TikZ). These are
    /// invisible to `ExtractedDocument.images` since they are not embedded as raster
    /// XObjects. Set to `true` when path count exceeds a heuristic threshold,
    /// signaling that downstream consumers may want to rasterize the page to
    /// capture this content.
    ///
    /// Only populated for PDFs; `null` for other document types.
    has_vector_graphics: bool,
};

/// Aggregate OCR legibility score for a page, reported by the backend that produced its text.
///
/// This is distinct from `OcrConfidence`, which scores a single detected element (a word or
/// line) using detection/recognition confidence from the OCR engine itself. `PageOcrConfidence`
/// is a page-level summary computed after noise filtering, intended for triage of which pages
/// are worth a closer look, not for comparing OCR engines against each other.
pub const PageOcrConfidence = struct {
    /// Aggregate legibility score in `0.0..=1.0`, or `null` when the backend that
    /// produced this page does not report a calibrated legibility scale.
    ///
    /// Backends differ in what their confidence numbers mean (see `OcrConfidence`'s
    /// per-backend normalization), and not every backend maps onto a 0.0-1.0 legibility
    /// scale at all. When a backend has no such calibrated scale, this is `null` rather
    /// than a misleading number, and scores must never be compared across backends.
    score: ?f64 = null,
    /// Number of words the score was averaged over, AFTER noise filtering.
    ///
    /// A small `word_count` means the average is based on little evidence, so a high
    /// `score` next to a small `word_count` is not representative of the whole page.
    word_count: u32,
    /// Name of the OCR backend that produced the page text.
    backend: []const u8,
};

/// A single page covered by a chunk, with an optional bounding box on that page.
///
/// See `ChunkMetadata.page_spans` (#1295) for population semantics.
pub const PageSpan = struct {
    /// Page number (1-indexed).
    page: u32,
    /// Bounding box on this page, if known.
    bbox: ?BoundingBox = null,
};

/// Unified page structure for documents.
///
/// Supports different page types (PDF pages, PPTX slides, Excel sheets)
/// with character offset boundaries for chunk-to-page mapping.
pub const PageStructure = struct {
    /// Total number of pages/slides/sheets
    total_count: u32,
    /// Type of paginated unit
    unit_type: PageUnitType,
    /// Character offset boundaries for each page
    ///
    /// Maps character ranges in the extracted content to page numbers.
    /// Used for chunk page range calculation.
    boundaries: ?[]const PageBoundary = null,
    /// Detailed per-page metadata (optional, only when needed)
    pages: ?[]const PageInfo = null,
};

/// A single built-in detection pattern and how its matches should be redacted.
pub const PatternMeta = struct {
    category: PiiCategory,
    pattern: []const u8,
    format_preserving: bool,
    redact_template: []const u8,
    /// Confidence a match gets when `validator` is absent, or returns
    /// `null` (no opinion). Defaults to `1.0` via `PatternMeta.new` so every pre-existing
    /// pattern keeps today's behavior; only patterns with a real checksum
    /// (`validators`) set this lower, since an unvalidated match in those
    /// categories is genuinely less certain than a plain regex hit.
    base_confidence: f32,
    /// Words that, found near a match, boost its confidence toward `1.0`
    /// (`context`). Empty for patterns with no calibrated context word list.
    context_words: []const []const u8,
};

/// A PDF annotation extracted from a document page.
pub const PdfAnnotation = struct {
    /// The type of annotation.
    annotation_type: PdfAnnotationType,
    /// Text content of the annotation (e.g., comment text, link URL).
    content: ?[]const u8 = null,
    /// Page number where the annotation appears (1-indexed).
    page_number: u32,
    /// Bounding box of the annotation on the page.
    bounding_box: ?BoundingBox = null,
    /// Author/creator of the annotation (PDF `/T` entry).
    author: ?[]const u8 = null,
    /// Last modification date of the annotation (PDF `/M` entry), as a raw
    /// PDF date string (e.g. `"D:20240115120000Z"`).
    modified: ?[]const u8 = null,
    /// Annotation colour (PDF `/C` entry), normalised to a CSS-compatible
    /// `#rrggbb` hex string. Gray and CMYK colour spaces are converted to RGB.
    color: ?[]const u8 = null,
    /// Subject of the annotation (PDF `/Subj` entry).
    subject: ?[]const u8 = null,
    /// Per-line bounding boxes derived from the annotation's `/QuadPoints`
    /// entry. Present for text markup annotations (Highlight, Underline,
    /// StrikeOut, Squiggly), one box per marked line/run of text.
    quad_points: ?[]const BoundingBox = null,
    /// The document text covered by `Self.quad_points`, recovered from the
    /// page content underneath the marked-up region. Populated for
    /// Highlight, Underline, StrikeOut, and Squiggly annotations when the
    /// underlying text could be recovered.
    marked_text: ?[]const u8 = null,
};

/// A form field extracted from a PDF's AcroForm or XFA structure.
///
/// Populated by the PDF extractor when `PdfConfig.extract_form_fields` is
/// enabled and the document is a fillable form. Supports both AcroForm (standard)
/// and XFA (XML Forms Architecture) layers. When both are present, AcroForm fields
/// take priority (canonical fallback per PDF spec), and XFA-only fields are appended.
/// The collection is empty for non-form PDFs and for non-PDF formats.
pub const PdfFormField = struct {
    /// Partial field name (the leaf name within the field hierarchy).
    name: []const u8,
    /// Fully-qualified field name (dotted path from the form root).
    full_name: []const u8,
    /// Classified field type.
    field_type: FormFieldType,
    /// Current field value, if any.
    value: ?[]const u8 = null,
    /// Default field value, if any.
    default_value: ?[]const u8 = null,
    /// Raw field-flags bitmask (read-only, required, multiline, …).
    flags: u32,
    /// 1-indexed page the field's widget appears on. Currently always `null` for
    /// AcroForm fields; page assignment is a deferred enhancement requiring spatial
    /// analysis of widget annotations per page.
    page: ?u32 = null,
    /// Widget bounding box on its page, if known.
    bbox: ?BoundingBox = null,
    /// Maximum input length for text fields, if specified.
    max_length: ?u32 = null,
    /// Tooltip / alternate field description, if present.
    tooltip: ?[]const u8 = null,
};

pub const PiiIncident = struct {
    summary: []const u8,
    timeline: []const u8,
    root_cause: []const u8,
    detected_at: []const u8,
    contained_at: ?[]const u8 = null,
    resolved_at: ?[]const u8 = null,
    actions_taken: []const []const u8,
    lessons_learned: []const []const u8,
};

/// Effective configuration for one `PiiPipeline`.
pub const PipelineConfig = struct {
    /// Prefer deterministic regex spans over model spans when the two overlap.
    regex_first: bool,
    /// Model detections scoring below this are discarded before merging.
    model_threshold_default: f32,
    /// Per-category threshold overrides — when a category is present here its value
    /// is used instead of `model_threshold_default`. Empty (default) means
    /// `effective_threshold` applies the hybrid persona-boost table.
    model_thresholds: std.StringHashMap(f32),
    /// Overlap ratio above which two spans are treated as the same detection.
    merge_overlap_threshold: f32,
    redaction: RedactionConfig,
    audit: AuditConfig,
    model: ModelConfig,
    /// How many documents `process_batch_with_auth` runs
    /// through this pipeline at once.
    ///
    /// `1` is the default and preserves the pipeline's original strictly-sequential
    /// behaviour. Raising it bounds a worker pool over the batch's documents — it does
    /// not change what is returned: results still come back in input order (see
    /// `HaciendaResult.pii`) and every document is still audited and reviewed exactly
    /// once, regardless of completion order.
    concurrency: u64,
    /// The Tier 0 schema vertical bound to this pipeline, if any.
    ///
    /// `null` (the default) is a strict no-op: nothing about detection changes unless
    /// an operator explicitly writes a `[pii.vertical]` section. See
    /// `superpowers/specs/2026-07-31-vertical-model-specialisation-design.md` §4.1 and
    /// `VerticalConfig`.
    ///
    /// There is deliberately no `verticals` array or selector — one optional vertical,
    /// bound at pipeline construction. A registry is premature abstraction at N=1; see
    /// the implementation plan's "Explicit Non-Goals".
    vertical: ?VerticalConfig = null,
};

/// Per-stage timings and counts for one `process` call.
pub const PipelineMetrics = struct {
    regex_ms: u64,
    model_ms: u64,
    merge_ms: u64,
    redaction_ms: u64,
    total_ms: u64,
    entities_detected: u32,
    entities_redacted: u32,
};

/// Everything one `process` call produced.
pub const PipelineResult = struct {
    /// Input text with every merged span rewritten. Equal to the input for `PiiPipeline.scan`.
    redacted_text: []const u8,
    entities: []const MergedEntity,
    audit_log: []const RedactionAuditEntry,
    metrics: PipelineMetrics,
};

