/// One hash-chained record of a single redacted span.
pub const RedactionAuditEntry = struct {
    category: []const u8,
    /// The rewrite that was applied — not merely the mode that was configured.
    ///
    /// `RedactionAction.Custom` carries the
    /// template text, because "a custom template was used" does not answer the question
    /// an auditor is asking. Built by
    /// `RedactionEngine`, the only place the
    /// template is in scope.
    action: RedactionAction,
    /// Which detector produced the span. Needed to attribute a redaction in the
    /// persistent audit chain without re-running detection.
    source: PiiEntitySource,
    /// blake3 digest of the original span. The span itself is never recorded.
    span_hash: []const u8,
    span_length: u32,
    confidence: ?f32 = null,
    timestamp: u64,
    chain_hash: []const u8,
};

pub const RedactionConfig = struct {
    mode: RedactionMode,
    /// Template used when `mode` is `RedactionMode.Custom`.
    ///
    /// `{{ENTITY}}` expands to the category name and `{{TEXT}}` to the original span.
    custom_template: ?[]const u8 = null,
    /// Keep the shape of the original span (length, separators) where the mode allows it.
    preserve_format: bool,
    /// Which pseudonymisation key new tokens are minted under, when `mode` is
    /// `RedactionMode.Pseudonymize`. `null` means "whichever key the resolver reports
    /// as active".
    ///
    /// This is an *identifier*, never key material. The struct is serialised and printed
    /// by `config show`; putting a secret in it would put that secret in every dumped
    /// config, log line, and support bundle. Key material reaches the engine only through
    /// a `KeyResolver`.
    key_id: ?[]const u8 = null,
};

/// One redaction event: which span was rewritten, why, and with what.
pub const RedactionFinding = struct {
    /// Byte-offset start in the original (pre-redaction) `ExtractedDocument.content`.
    start: u32,
    /// Byte-offset end (exclusive) in the original `ExtractedDocument.content`.
    end: u32,
    /// PII category that fired this redaction.
    category: XbergPiiCategory,
    /// Strategy applied to this finding (mask, hash, token-replace, drop).
    strategy: RedactionStrategy,
    /// String that replaced the original mention. Always present; for `Drop` the
    /// replacement is the empty string.
    replacement_token: []const u8,
};

pub const RedactionMetrics = struct {
    redaction_ms: u64,
    entities_detected: u32,
    entities_redacted: u32,
};

/// One user-supplied regex pattern to redact.
///
/// The pattern is compiled with the Rust `regex` crate (no look-around). Case
/// sensitivity is encoded in the pattern via the `(?i)` inline flag when
/// `Self.case_sensitive` is `false`.
pub const RedactionPattern = struct {
    /// Custom category label surfaced in `RedactionFinding.category`.
    label: []const u8,
    /// Regex pattern (Rust `regex` crate dialect — no look-around).
    pattern: []const u8,
    /// When `true`, match case-sensitively; otherwise prepend `(?i)` to the regex.
    case_sensitive: bool,
};

/// Audit report describing what the redaction processor found and how it replaced it.
///
/// The redactor returns this alongside the rewritten content so compliance, replay, and
/// audit-log consumers can see exactly what fired. Offsets are relative to the *original*
/// pre-redaction `content` and are intended for audit reconstruction only — the original
/// bytes are dropped at the end of the pipeline.
pub const RedactionReport = struct {
    /// Individual redaction findings in original-source byte order.
    findings: []const RedactionFinding,
    /// Total number of redactions applied across the document.
    total_redacted: u32,
};

pub const RedactionResult = struct {
    text: []const u8,
    audit_log: []const RedactionAuditEntry,
    metrics: RedactionMetrics,
};

/// One user-supplied literal term to redact.
///
/// Matched as a regex-escaped substring (so callers do not need to escape
/// metacharacters themselves). Case-insensitive by default — set
/// `Self.case_sensitive` to `true` for exact byte-match semantics.
pub const RedactionTerm = struct {
    /// Custom category label surfaced in `RedactionFinding.category`.
    label: []const u8,
    /// Literal value to match. Regex metacharacters are escaped automatically.
    value: []const u8,
    /// When `true`, match the value as-is; otherwise match ASCII-case-insensitively.
    case_sensitive: bool,
};

/// A span matched by the deterministic regex engine.
pub const RegexEntity = struct {
    category: PiiCategory,
    /// Byte offset of the first byte of the span.
    start: u32,
    /// Byte offset one past the last byte of the span.
    end: u32,
    confidence: f32,
    format_preserving: bool,
    redact_template: []const u8,
    /// Copied from the originating `PatternMeta.context_words` at match time, so
    /// `enhance` can look up this span's context words without
    /// needing the pattern set that produced it back in scope. `#[serde(skip)]`: a
    /// `&'static` slice cannot round-trip through serde, and (as with
    /// `PatternMeta.validator`) nothing actually (de)serializes `RegexEntity` today.
    context_words: []const []const u8,
};

/// A request to mint a `RevealTicket`. This is what contract B's `RehydrationRequest`
/// becomes at the authorization boundary: the *demand*, before the ticket is granted.
pub const RevealTicketRequest = struct {
    /// Dossier the subject must belong to (ACL gate at mint time).
    dossier_id: []const u8,
    /// Documents in scope — must be non-empty and contain no empty id.
    document_ids: []const []const u8,
    /// Explicit token ids in scope. Shape-checked at mint; unknown keys stay fail-closed
    /// (400) at resolve time, never at mint time, so minting is not a token oracle.
    token_ids: []const []const u8,
    /// Category labels in scope, as an alternative to `token_ids`. At least one of
    /// `token_ids` / `field_scope` must be non-empty.
    field_scope: []const []const u8,
    /// Required, non-blank justification. Written verbatim to the audit entry.
    justification: []const u8,
    /// Approvers. High-sensitivity scopes require >= 2 distinct approvers != subject.
    approvers: []const []const u8,
    /// Optional TTL in seconds; clamped to `[MIN_TICKET_TTL_SECS, MAX_TICKET_TTL_SECS]`,
    /// defaulting to `DEFAULT_TICKET_TTL_SECS`.
    ttl_secs: ?u64 = null,
};

