/// Token-only search data. Search consumers can match opaque IDs/equality without ever
/// receiving a plaintext index.
pub const SearchProjection = struct {
    tokens: []const SearchToken,
};

pub const SearchToken = struct {
    token_class: []const u8,
    token_id: []const u8,
    mode: []const u8,
    source: []const u8,
    disclosure_state: []const u8,
    occurrences: u32,
