/// Configuration for security limits across extractors.
///
/// All limits are intentionally conservative to prevent DoS attacks
/// while still supporting legitimate documents.
pub const SecurityLimits = struct {
    /// Maximum uncompressed size for archives (500 MB)
    max_archive_size: u64,
    /// Maximum compression ratio before flagging as potential bomb (100:1)
    max_compression_ratio: u64,
    /// Maximum number of files in archive (10,000)
    max_files_in_archive: u64,
    /// Maximum nesting depth for structures (1024)
    max_nesting_depth: u64,
    /// Maximum length of any single XML entity / attribute / token (1 MiB).
    /// This is a per-token cap, NOT a total cap — billion-laughs class
    /// attacks where a single entity expands to hundreds of MB are caught
    /// here, while normal long text content (a paragraph, a CDATA block) is
    /// caught by `max_content_size` instead.
    max_entity_length: u64,
    /// Maximum string growth and decoded image allocation per operation (100 MB).
    ///
    /// Per-page passes such as layout detection charge each batch against this limit,
    /// not the whole document; only `max_pages` bounds the rasters retained across a
    /// document (GH#1721).
    max_content_size: u64,
    /// Maximum iterations per operation.
    ///
    /// For external redaction findings, this may lower but cannot raise the
    /// fixed 10,000-finding ceiling.
    max_iterations: u64,
    /// Maximum XML depth (1024 levels)
    max_xml_depth: u64,
    /// Maximum aggregate table cells per document (100,000).
    ///
    /// Raise this for trusted large tabular inputs. Higher values permit
    /// proportionally more parsing work and output allocation. A spreadsheet
    /// workbook (XLSX, XLSM, XLTM, XLAM, XLSB, XLS, XLA, ODS) over the limit is not rejected: each
    /// sheet that does not fit the remaining budget is skipped with a warning
    /// and returned empty, so a workbook whose every sheet is over the limit
    /// yields placeholder sheets only. Other table formats fail with a
    /// security error.
    max_table_cells: u64,
    /// Maximum number of pages (or slides, or frames) in a single document.
    /// `null` means unlimited.
    ///
    /// Checked once the count is known and before any per-page work (OCR, layout
    /// detection, rendering) starts. Byte-size limits do not bound page count: a
    /// scanned page can compress to a few kilobytes, so a document well under
    /// `max_content_size` or `max_archive_size` can still hold thousands of pages
    /// of per-page work. Defaults to `null` (unlimited) because a real ceiling
    /// here is workload-specific and a low default would silently reject
    /// legitimate large documents; callers that want a ceiling set this
    /// explicitly.
    ///
    /// Enforced for: PDF (`extractors.pdf`, page count via `xberg_native_pdf`/`lopdf`),
    /// PPTX (`extraction.pptx`, slide count from the archive's slide parts),
    /// Keynote (`extractors.iwork.keynote`, slide count from `Index/Slide-*.iwa`
    /// entry names), ODP (`extractors.odp`, `draw:page` count in `content.xml`),
    /// and multi-frame TIFF images built with the `ocr` feature
    /// (`extractors.image`, frame count via the `tiff` crate). Not enforced for
    /// any other format, including DOCX, ODT, XLSX, legacy PPT/DOC, Pages/Numbers,
    /// and TIFF images when the `ocr` feature is disabled: those formats either
    /// have no fixed "page" the crate can count without doing the expensive work
    /// itself (DOCX/ODT page count is a layout outcome, not a stored value), or
    /// have no per-page pipeline to gate at all. Setting `max_pages` on a
    /// document of an unenforced format is silently a no-op, not a guarantee.
    max_pages: ?u64 = null,
};

/// The immutable record left behind when a segment is closed.
///
/// `seal_hash` commits to every other field, including `prev_seal_hash`, so that a node's
/// seals form a hash chain of segments — the same construction as the entry chain, one
/// level up.
///
/// That back-pointer is what makes truncation detectable, and truncation is the attack the
/// segment layer would otherwise be wide open to. Without it, an attacker could delete a
/// node's oldest segment, blank the successor's `prev_seal_hash`, and present the remainder
/// as a complete history: every surviving segment verifies internally, and every link
/// between survivors holds. Suppressing the earliest records is precisely what a
/// tamper-evident log exists to prevent, so the cost — one hash input — is not worth
/// arguing about.
///
/// `entry_count` is in the preimage as a cheaper, more legible integrity signal rather than
/// as a distinct security property. `sealed_tip` already changes when entries are removed,
/// since the tip *is* the last entry's chain hash. What `entry_count` adds is an invariant a
/// store can assert at recovery — replayed entries must number exactly this many — which
/// fails with "expected 40 entries, found 37" instead of an opaque hash mismatch.
pub const SegmentSeal = struct {
    segment_id: []const u8,
    /// The tenant this segment belongs to (S1 spec §5). Always `"default"` until the
    /// store that produced this seal is itself threaded with a real tenant context —
    /// see `Segment.tenant_id`'s doc comment.
    ///
    /// Defaulted on deserialize (mirroring `review.types.ReviewQueueItem.tenant_id`):
    /// a `*.seal.json` file written by any pre-S1 build has no `tenant_id` key at all, so
    /// without this, loading it back would fail outright with a missing-field error
    /// instead of defaulting to `"default"`.
    tenant_id: []const u8,
    node_id: []const u8,
    config_hash: []const u8,
    /// Seal hash of the immediately preceding segment on this node, or `null` for the
    /// first segment. Committed into `seal_hash` so deletion of the predecessor is
    /// detectable.
    prev_seal_hash: ?[]const u8 = null,
    /// Entry chain tip at seal time.
    sealed_tip: []const u8,
    /// Number of entries in the segment at seal time.
    entry_count: u64,
    /// RFC 3339 timestamp when the segment was opened.
    opened_at: []const u8,
    /// RFC 3339 timestamp when the segment was sealed.
    sealed_at: []const u8,
    /// blake3 over all other fields. Recompute with `compute_seal_hash` and compare to
    /// detect any post-seal modification.
    seal_hash: []const u8,
};

/// A token reference used in marks, metadata, and search results.
pub const SensitiveToken = struct {
    /// The opaque token text itself, not the value it represents.
    token_id: []const u8,
    token_class: []const u8,
    mode: []const u8,
    source: []const u8,
    disclosure_state: []const u8,
};

/// A source-text redaction record safe to send alongside an editor document.
///
/// This type intentionally contains no matched text, hashes, or metadata values. Offsets
/// are evidence about the source that was redacted, not offsets into the editor projection.
pub const SourceRedactionProvenance = struct {
    token_class: []const u8,
    token_id: ?[]const u8 = null,
    start: u32,
    end: u32,
    source: EntitySource,
    mode: RedactionMode,
};

/// A sparse learned embedding: vocabulary term indices and their weights.
///
/// `indices` are ascending vocabulary token ids; `values[i]` is the weight for
/// `indices[i]`. The two arrays always have equal length. Only strictly-positive
/// terms are retained, so the representation is genuinely sparse.
pub const SparseEmbedding = struct {
    /// Vocabulary token ids with non-zero weight, ascending.
    indices: []const u32,
    /// Weights parallel to `SparseEmbedding.indices`.
    values: []const f32,
};

/// Configuration for the sparse-embedding pipeline.
///
/// Controls which model to use, batching, and download/cache behavior for the
/// local ONNX SPLADE model.
pub const SparseEmbeddingConfig = struct {
    /// The sparse-embedding model to use (defaults to the "opensearch-v3-distill" preset).
    model: SparseEmbeddingModelType,
    /// Batch size for local ONNX inference.
    ///
    /// SPLADE emits a `[seq, vocab]` logit tensor per document, so memory scales
    /// with batch size — keep this modest.
    batch_size: u64,
    /// Maximum token sequence length for the tokenizer.
    max_length: u64,
    /// Show model download progress (local ONNX path only).
    ///
    /// When enabled, transfer progress for the model, tokenizer and config files is reported at
    /// `info` level on the `xberg.model_download` target while they download (#279). A warm
    /// Hugging Face cache transfers nothing and so reports nothing. Ignored by
    /// `SparseEmbeddingModelType.Plugin`, which downloads no model.
    show_download_progress: bool,
    /// Optional alternate Hugging Face cache root for model files.
    ///
    /// When unset, hf-hub follows the standard Hugging Face environment and
    /// platform cache conventions.
    cache_dir: ?[]const u8 = null,
    /// Hardware acceleration for the sparse-embedding ONNX model.
    acceleration: ?AccelerationConfig = null,
    /// Maximum wall-clock duration (in seconds) for a single embed call when
    /// using `SparseEmbeddingModelType.Plugin`. `null` disables the timeout.
