/// A Tier 0 "schema vertical": a named set of zero-shot labels handed to the NER
/// backend *in addition to* the base categories (`Person`, `Organization`, `Location`,
/// `Email`, `Phone`). No weights are loaded and no model is reloaded — a vertical is
/// arguments to an inference call, nothing more. See
/// `superpowers/specs/2026-07-31-vertical-model-specialisation-design.md` §4.1.
///
/// # Footgun: the alias-table collision
///
/// `to_pii_category` maps some `Custom` label strings onto existing
/// `PiiCategory` variants *before* they would otherwise become
/// `PiiCategory.Custom(label)` — for example the label `"iban"` (case-insensitively)
/// becomes `Iban`, not `Custom("iban")`. A vertical author
/// who picks a label that happens to collide with that alias table gets the aliased
/// category's downstream behaviour (its pseudonym token name, its place in exports,
/// its interaction with other detectors) instead of a bespoke `Custom` category. This
/// is deliberate for the *known* aliases (a vertical calling something `"iban"` should
/// get real IBAN handling) but is easy to trip over by accident with a near-miss label
/// (`"iban_number"` does *not* alias and stays `Custom("iban_number")`). Check
/// `to_pii_category`'s alias table before choosing a label if the distinction matters
/// to you.
pub const VerticalConfig = struct {
    /// Stable identifier recorded in the audit chain.
    id: []const u8,
    /// Zero-shot labels handed to the NER backend in addition to the base categories.
    labels: []const []const u8,
};

/// Configuration for the redaction post-processor.
pub const XbergRedactionConfig = struct {
    /// Categories to redact. Empty means "every category supported by the engine."
    categories: []const XbergPiiCategory,
    /// Strategy applied to every match.
    strategy: RedactionStrategy = .mask,
    /// Optional NER backend — required to redact PERSON / ORGANIZATION / LOCATION
    /// categories (the pure-Rust pattern engine only covers regex-detectable PII).
    ner: ?NerConfig = null,
    /// When `true`, chunk byte ranges are kept consistent with the rewritten content by
    /// adjusting `byte_start` / `byte_end` after replacement. When `false`, chunk byte
    /// ranges still refer to the *original* content offsets — useful when downstream
    /// consumers want to map findings back to the original document.
    preserve_offsets: bool,
    /// Arbitrary user-supplied literal terms to redact.
    ///
    /// Each term is treated as a regex hit against the document, surfacing as
    /// `PiiCategory.Custom(label)` in `RedactionFinding`
    /// where `label` is the per-term label (defaulting to the literal value itself).
    /// Case-insensitive by default; set `RedactionTerm.case_sensitive` for exact match.
    ///
    /// Use this when you need to redact tenant-specific tokens (employee IDs,
    /// project codes, internal product names) without writing a custom plugin.
    custom_terms: []const RedactionTerm,
    /// Arbitrary user-supplied regex patterns to redact.
    ///
    /// Same surfacing semantics as `custom_terms`: each
    /// hit becomes a `PiiCategory.Custom(label)` finding. Patterns are validated
    /// at config-construction time via `RedactionConfig.validate`.
    custom_patterns: []const RedactionPattern,
    /// Findings supplied inline by an external inspection engine.
    findings: []const ExternalRedactionFinding,
    /// Minimum accepted confidence for scored external findings. Findings without a score remain eligible.
    min_score: ?f32 = null,
    /// JSON array or JSON Lines file containing external findings.
    findings_path: ?[]const u8 = null,
    /// Unit used by configured findings that derive their text from offsets.
    findings_offset_encoding: RedactionOffsetEncoding = .unicode_code_points,
};

