/// The redaction that was applied to a span, as recorded in the audit log.
///
/// `Reveal` is included because an audit chain that omits "who accessed the
/// unredacted span text" is not credible for a compliance product — see §7 of
/// the design spec. The `span_hash` field on the entry carries the digest of
/// the revealed text so the record is non-repudiable without storing the
/// plaintext.
pub const RedactionAction = union(enum) {
    mask: void,
    hash: void,
    pseudonymize: void,
    remove: void,
    /// Span text was returned to an authorised caller in plaintext form.
    ///
    /// Only appended when `SpanText.Include` is used with a `Caller.Principal`
    /// that holds `Capability.PiiReveal`. The `span_hash` field on the entry
    /// carries the blake3 digest of the revealed text.
    reveal: void,
    custom: []const u8,
};

/// How a detected span is rewritten in the output text.
pub const RedactionMode = enum {
    /// Replace with the category's redaction template, e.g. `[EMAIL]`.
    ///
    /// The default, because it is the only mode that is both irreversible and needs no
    /// configuration. A default of `RedactionMode.Pseudonymize` would mean the
    /// out-of-the-box path depends on a secret the operator has not yet set.
    mask,
    /// Replace with a short blake3 digest of the original span.
    hash,
    /// Replace with a keyed, reversible token, e.g. `[EMAIL:k1:MZXW6YTB...]`.
    ///
    /// Equal values get equal tokens, so a reader can follow one pseudonymous person
    /// through a corpus, and a holder of the key can reverse it. Requires a key: see
    /// `RedactionEngine.new`.
    pseudonymize,
    /// Delete the span entirely.
    remove,
    /// Replace using `RedactionConfig.custom_template`.
    custom,
};

