/// Alias with a descriptive name for callers that prefer the output type as the verb.
pub fn build_editor_projection(document: []const u8, options: []const u8) error{ OutOfMemory, InvalidJson }![]u8 {
    const document_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{document}, 0);
    defer std.heap.c_allocator.free(document_z);
    const document_handle = c.hacienda_extracted_document_from_json(document_z);
    if (document_handle == 0) return error.InvalidJson;
    defer c.hacienda_extracted_document_free(document_handle);
    const options_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{options}, 0);
    defer std.heap.c_allocator.free(options_z);
    const options_handle = c.hacienda_editor_projection_options_from_json(options_z);
    if (options_handle == 0) return error.InvalidJson;
    defer c.hacienda_editor_projection_options_free(options_handle);
    const _result = c.hacienda_build_editor_projection(document_handle, options_handle);
    return blk: {
        if (_result == 0) return error.OutOfMemory;
        const value = _result;
        defer c.hacienda_editor_envelope_free(value);
        const _json_ptr = c.hacienda_editor_envelope_to_json(value);
        if (_json_ptr == null) return error.OutOfMemory;
        defer _free_string(_json_ptr);
        const slice = std.mem.sliceTo(_json_ptr, 0);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// The deterministic pattern set the `RegexEngine` compiles.
///
/// Order matters: earlier patterns win when two matches overlap, because
/// `RegexEngine.find_all` sorts by start offset and drops later overlapping spans.
pub fn builtin_patterns() error{ OutOfMemory, UnknownFfiError, Cancelled }![]u8 {
    const _result = c.hacienda_builtin_patterns();
    if (_result == null) {
        return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    }
    const _result_len = c.hacienda_builtin_patterns_len();
    return blk: {
        const slice = _result[0.._result_len];
        defer _free_string(_result);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

pub fn cache_stats() error{ OutOfMemory, UnknownFfiError, Cancelled }!CacheStats {
    const _result = c.hacienda_cache_stats();
