/// Compute the chain hash linking an entry to its predecessor.
///
/// The timestamp is deliberately excluded so verification is reproducible.
pub fn compute_chain_hash(prev_chain_hash: []const u8, seq: u64, fields: ChainHashFields) error{ OutOfMemory, UnknownFfiError, Cancelled }![]u8 {
    const prev_chain_hash_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{prev_chain_hash}, 0);
    defer std.heap.c_allocator.free(prev_chain_hash_z);
    const _result = c.hacienda_compute_chain_hash(prev_chain_hash_z, seq, fields);
    if (_result == null) {
        return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    }
    const _result_len = c.hacienda_compute_chain_hash_len(prev_chain_hash_z, seq, fields);
    return blk: {
        const slice = _result[0.._result_len];
        defer _free_string(_result);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// Compute the blake3 hash that seals a segment's metadata.
///
/// Every field is length-prefixed before being fed to the hasher. This prevents
/// ambiguous splits: without length prefixes, `("ab", "c")` and `("a", "bc")` would
/// produce the same byte sequence. `compute_chain_hash` in `entry.rs` uses fixed-width
/// integers (which are self-delimiting) alongside string bytes and does not need this
/// guard, but the seal fields are all variable-length strings, so it is required here.
///
/// The field order and encoding here is the canonical definition of the seal hash for
/// this library. Changing either breaks all stored seals.
///
/// The nine arguments map one-to-one to the nine `SegmentSeal` fields that the hash
/// covers. Wrapping them in a struct would force callers to construct one just to call this
/// function; keeping them flat is both more legible and consistent with `compute_chain_hash`.
pub fn compute_seal_hash(prev_seal_hash: ?[]const u8, segment_id: []const u8, tenant_id: []const u8, node_id: []const u8, config_hash: []const u8, sealed_tip: []const u8, entry_count: u64, opened_at: []const u8, sealed_at: []const u8) error{ OutOfMemory, UnknownFfiError, Cancelled }![]u8 {
    const prev_seal_hash_z: ?[:0]u8 = if (prev_seal_hash) |v| try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{v}, 0) else null;
    defer if (prev_seal_hash_z) |z| std.heap.c_allocator.free(z);
    const segment_id_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{segment_id}, 0);
    defer std.heap.c_allocator.free(segment_id_z);
    const tenant_id_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{tenant_id}, 0);
    defer std.heap.c_allocator.free(tenant_id_z);
    const node_id_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{node_id}, 0);
    defer std.heap.c_allocator.free(node_id_z);
    const config_hash_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{config_hash}, 0);
    defer std.heap.c_allocator.free(config_hash_z);
    const sealed_tip_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{sealed_tip}, 0);
    defer std.heap.c_allocator.free(sealed_tip_z);
    const opened_at_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{opened_at}, 0);
    defer std.heap.c_allocator.free(opened_at_z);
    const sealed_at_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{sealed_at}, 0);
    defer std.heap.c_allocator.free(sealed_at_z);
    const _result = c.hacienda_compute_seal_hash(if (prev_seal_hash_z) |z| z.ptr else null, segment_id_z, tenant_id_z, node_id_z, config_hash_z, sealed_tip_z, entry_count, opened_at_z, sealed_at_z);
    if (_result == null) {
        return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    }
    const _result_len = c.hacienda_compute_seal_hash_len(if (prev_seal_hash_z) |z| z.ptr else null, segment_id_z, tenant_id_z, node_id_z, config_hash_z, sealed_tip_z, entry_count, opened_at_z, sealed_at_z);
    return blk: {
        const slice = _result[0.._result_len];
        defer _free_string(_result);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

pub fn detect_mime_type(bytes: []const u8, filename: ?[]const u8) error{ OutOfMemory, UnknownFfiError, Cancelled }![]u8 {
    const filename_z: ?[:0]u8 = if (filename) |v| try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{v}, 0) else null;
    defer if (filename_z) |z| std.heap.c_allocator.free(z);
    const _result = c.hacienda_detect_mime_type(bytes.ptr, bytes.len, if (filename_z) |z| z.ptr else null);
    if (c.hacienda_last_error_code() != 0) {
        return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    }
    if (_result == null) {
        return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    }
    const _result_len = c.hacienda_detect_mime_type_len(bytes.ptr, bytes.len, if (filename_z) |z| z.ptr else null);
    return blk: {
        if (_result == null) return error.UnknownFfiError;
