    /// and predecessor hash are consistent, which `append` only verifies.
    /// `input.config_hash` is overwritten with the chain's own config hash.
    pub fn push(self: *AuditChain, input: AuditEntryInput) error{ OutOfMemory, HandleClosed }![]u8 {
