        if (entry_handle == 0) return error.UnknownFfiError;
        defer c.hacienda_audit_entry_free(entry_handle);
        _ = c.hacienda_audit_chain_append(handle, entry_handle);
        if (c.hacienda_last_error_code() != 0) {
