    pub fn close(self: *FileAuditStore, tenant: TenantId) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
