    const config_z = try std.heap.c_allocator.dupeSentinel(u8, config, 0);
    defer std.heap.c_allocator.free(config_z);
    const config_handle = c.hacienda_hacienda_config_from_json(config_z.ptr);
    if (config_handle == 0) return error.InvalidJson;
    defer c.hacienda_hacienda_config_free(config_handle);
    const _handle = c.hacienda_hacienda_facade_with_key_resolver(config_handle, resolver, retired_z.ptr);
    if (_handle == 0) return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    return .{ ._handle = _handle };
}

