    /// distinguish "no store" from "store with no entries yet".
    pub fn audit_entries(self: *HaciendaFacade) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
