            break :blk owned;
        };
    }

    /// Process several inputs as one extraction, sharing the audit chain and glossary.
    ///
    /// **Errors:**
    ///
    /// As `HaciendaFacade.process`.
    pub fn process_batch(self: *HaciendaFacade, inputs: []const u8) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
