    /// Returns `HaciendaError.Pii` if PII is not enabled or detection fails.
    pub fn redact_text(self: *HaciendaFacade, text: []const u8) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
