/// An in-memory implementation of `AuditStore`.
///
/// State is discarded on drop. This is the right default for testing and for short-lived
/// CLI invocations where durability is not required. For a process that must survive a
/// restart with its audit record intact, use the file backend from Task 3 instead.
///
/// One `State` per tenant, lazily created on that tenant's first call — not one
/// `InMemoryAuditStore` per tenant (see the trait doc's "Tenant scoping" section for why).
/// `node_id`/`config_hash` are shared: this is one writer node serving many tenants, each
/// with its own independent chain.
///
/// # Locking discipline
///
/// Each method acquires exactly one lock, does all of its work, then drops the guard
/// before returning — no guard crosses an `.await` point. The in-memory backend does no
/// I/O, so there is nothing to await while holding a guard. The file backend in Task 3
/// has to be more careful: it must build the byte buffer under the lock, drop the guard,
/// then `spawn_blocking` the write. A guard held across an `await` makes the future
/// `!Send`, which will not compile behind `Arc<dyn AuditStore>`.
pub const InMemoryAuditStore = struct {
    _handle: u64,

    pub fn append(self: *InMemoryAuditStore, tenant: TenantId, inputs: []const u8) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const inputs_z = try std.heap.c_allocator.dupeSentinel(u8, inputs, 0);
        defer std.heap.c_allocator.free(inputs_z);
        const _result = c.hacienda_in_memory_audit_store_append(handle, tenant_handle, inputs_z);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    pub fn entries(self: *InMemoryAuditStore, tenant: TenantId) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_in_memory_audit_store_entries(handle, tenant_handle);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    /// The whole history is already in memory, so the guard is simply held for the
    /// duration — the page is assembled from borrowed state and nothing is awaited inside.
    /// Snapshotting first, as `verify` does, would copy every entry ever written just to
    /// hand back at most `limit` of them.
    ///
    /// Sealed extents are taken from each **seal**'s `entry_count`, not from the length of
    /// the vector beside it. The seal is the immutable record; disagreement between the
    /// two is exactly what `AuditError.SegmentEntryCount` reports, and reading the
    /// length would define that discrepancy out of existence.
    pub fn history(self: *InMemoryAuditStore, tenant: TenantId, after: ?AuditCursor, limit: u64) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })!AuditPage {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_in_memory_audit_store_history(handle, tenant_handle, after, limit);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk AuditPage{ ._handle = _result };
        };
    }

    pub fn tip(self: *InMemoryAuditStore, tenant: TenantId) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_in_memory_audit_store_tip(handle, tenant_handle);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    pub fn seals(self: *InMemoryAuditStore, tenant: TenantId) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_in_memory_audit_store_seals(handle, tenant_handle);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    pub fn verify(self: *InMemoryAuditStore, tenant: TenantId) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        _ = c.hacienda_in_memory_audit_store_verify(handle, tenant_handle);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
    }

    pub fn rotate(self: *InMemoryAuditStore, tenant: TenantId) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_in_memory_audit_store_rotate(handle, tenant_handle);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            const value = _result;
            defer c.hacienda_segment_seal_free(value);
            const _json_ptr = c.hacienda_segment_seal_to_json(value) orelse return error.OutOfMemory;
            defer c.hacienda_free_string(_json_ptr);
            const _json_slice = std.mem.span(_json_ptr);
            const owned = try std.heap.c_allocator.dupe(u8, _json_slice);
            break :blk owned;
        };
    }

    pub fn close(self: *InMemoryAuditStore, tenant: TenantId) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_in_memory_audit_store_close(handle, tenant_handle);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            const value = _result;
            defer c.hacienda_segment_seal_free(value);
            const _json_ptr = c.hacienda_segment_seal_to_json(value) orelse return error.OutOfMemory;
            defer c.hacienda_free_string(_json_ptr);
            const _json_slice = std.mem.span(_json_ptr);
            const owned = try std.heap.c_allocator.dupe(u8, _json_slice);
            break :blk owned;
        };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *InMemoryAuditStore) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.hacienda_in_memory_audit_store_free(handle);
    }
