/// fail-closed direction (no ownership proof ⇒ no ticket).
pub const InMemoryDocumentDossierIndex = struct {
    _handle: u64,

    /// Record that `document_id` belongs to `dossier_id` in `tenant`.
    pub fn index(self: *InMemoryDocumentDossierIndex, tenant: TenantId, document_id: []const u8, dossier_id: []const u8) error{ OutOfMemory, HandleClosed }!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
