/// Validate and wrap a key id.
///
/// **Errors:**
///
/// `PseudonymError.InvalidKeyId` if `id` is empty, longer than 16 characters, or
/// contains anything outside `[a-z0-9_]`.
pub fn new_key_id(id: []const u8) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{OutOfMemory})!KeyId {
    const id_z = try std.heap.c_allocator.dupeSentinel(u8, id, 0);
