    return .{ ._handle = _handle };
}

/// Identifies which key a token was minted under.
///
/// The id travels in the clear inside every token, which is what makes rotation additive:
/// a new key changes only what *new* tokens say, and old tokens keep naming the key that
/// can still read them (spec §12.3.1). It is not secret.
///
/// The charset is deliberately narrow — `[a-z0-9_]`, 1 to 16 characters:
///
/// - `:` and `]` are token structure. A key id containing either produces tokens that
///   cannot be parsed back.
///
/// - `-` is excluded even though it reads naturally as a separator, because the id is
///   uppercased into an environment variable name and `-` is not legal there. Folding it
///   to `_` would silently alias `k-1` and `k_1` onto one key.
///
/// - Uppercase is rejected rather than folded, so that exactly one spelling of an id maps
///   to one key and audit records cannot disagree about which key was used.
pub const KeyId = struct {
    _handle: u64,

    pub fn as_str(self: *KeyId) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_key_id_as_str(handle);
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *KeyId) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.hacienda_key_id_free(handle);
    }
};

/// Load the Candle GLiNER2 backend from a local model directory, optionally
/// merging a LoRA adapter.
///
/// Backends are cached process-wide by `(model_dir, lora_adapter_dir)`, so the
/// model-load and adapter-merge cost is paid once per pair rather than per document.
///
/// When `expected_weights_hash` is `Some`, the blake3 digest is checked against
/// the exact bytes handed to Candle, and the backend is built from those same
/// bytes via the uncached in-memory loader. A mismatch aborts with
/// `PiiError.Ner` so a tampered or corrupted model can never be executed.
/// That path intentionally rejects a LoRA adapter: merged adapter bytes cannot
/// be bound to the base-weights digest, so verification must fail closed.
///
/// Without a hash, the resulting detector reports `runtime_ready = true` with
/// no model id: a privately fine-tuned/unpinned model is still model-backed
/// even though there is no registry identity to report.
///
/// **Errors:**
///
