    defer std.heap.c_allocator.free(model_dir_z);
    const lora_adapter_dir_z = try std.heap.c_allocator.dupeSentinel(u8, lora_adapter_dir, 0);
    defer std.heap.c_allocator.free(lora_adapter_dir_z);
    const expected_weights_hash_z = try std.heap.c_allocator.dupeSentinel(u8, expected_weights_hash, 0);
    defer std.heap.c_allocator.free(expected_weights_hash_z);
    const _handle = c.hacienda_ner_detector_from_candle_local(model_dir_z.ptr, lora_adapter_dir_z.ptr, expected_weights_hash_z.ptr);
    if (_handle == 0) return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    return .{ ._handle = _handle };
}

