/// Runs an xberg NER backend and maps its entities into pipeline spans.
///
/// `Clone` is cheap (P3a): `backend` is already behind an `Arc`, and `categories`/
/// `threshold` are small owned data. This is what lets `HaciendaFacade`
/// (`hacienda-core/src/facade.rs`) build one detector once and construct a second,
/// per-tenant `PiiPipeline` from a clone of it without reloading the NER
/// backend's model weights.
///
/// `HaciendaFacade`: crate.HaciendaFacade
pub const NerDetector = struct {
    _handle: u64,

    /// Runtime identity of the backend this detector actually holds.
    pub fn runtime_state(self: *NerDetector) error{ OutOfMemory, HandleClosed }!NerRuntimeState {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_ner_detector_runtime_state(handle);
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk NerRuntimeState{ ._handle = _result };
        };
    }

    /// Drop entities the backend scores below `threshold`.
    ///
    /// Entities without a confidence score are kept: a backend that does not report
    /// confidence should not be silently filtered to nothing.
    ///
    /// # Candle GLiNER threshold floor
    ///
    /// `xberg.text.ner.candle.CandleBackend.detect` hard-codes an internal
    /// threshold of `0.5` before `NerDetector`'s own filter runs. Consequently
    /// `with_threshold` can only ever *raise* the effective threshold above `0.5`;
    /// it can never lower it. Entities the Candle backend scores below `0.5` are
    /// invisible at any configured threshold, so every recall figure measured
    /// through this detector is *truncated recall at 0.5*, not recall. This is an
    /// upstream xberg limitation, not something this library can work around without
    /// patching `CandleBackend.detect`.
    pub fn with_threshold(self: *NerDetector, threshold: f32) error{ OutOfMemory, HandleClosed }!NerDetector {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_ner_detector_with_threshold(handle, threshold);
        self._handle = 0;
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk NerDetector{ ._handle = _result };
        };
    }

    /// Detect entities in `text`.
    ///
    /// **Errors:**
    ///
    /// Returns `PiiError.Ner` if the backend fails.
    pub fn detect(self: *NerDetector, text: []const u8) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const text_z = try std.heap.c_allocator.dupeSentinel(u8, text, 0);
        defer std.heap.c_allocator.free(text_z);
        const _result = c.hacienda_ner_detector_detect(handle, text_z);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *NerDetector) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.hacienda_ner_detector_free(handle);
    }
};

