        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk KeyId{ ._handle = _result };
        };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *PseudonymKey) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.hacienda_pseudonym_key_free(handle);
    }
};

