            if (_result == 0) return error.OutOfMemory;
            const value = _result;
            defer c.hacienda_review_queue_item_free(value);
            const _json_ptr = c.hacienda_review_queue_item_to_json(value) orelse return error.OutOfMemory;
            defer c.hacienda_free_string(_json_ptr);
