/// One writer's contiguous run of audit entries, sealed when the writer stops.
///
/// A `Segment` owns an `AuditChain` that starts at `GENESIS_HASH` with `seq = 0`.
/// When writing is done, call `seal` to produce a `SegmentSeal` whose
/// `seal_hash` commits to all segment metadata including `prev_seal_hash` from the
/// predecessor, making any later deletion of the predecessor detectable.
pub const Segment = struct {
    _handle: u64,

    /// Mint an entry at the current tip and append it.
    ///
    /// Delegates to `AuditChain.push`, which stamps the chain's own config hash onto
    /// the input. Segment and chain are given the same config hash at
    /// `open`, so a caller cannot put the two out of step.
    pub fn push(self: *Segment, input: AuditEntryInput) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const input_handle = input._handle;
        if (input_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_segment_push(handle, input_handle);
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            const value = _result;
            defer c.hacienda_audit_entry_free(value);
            const _json_ptr = c.hacienda_audit_entry_to_json(value) orelse return error.OutOfMemory;
            defer c.hacienda_free_string(_json_ptr);
            const _json_slice = std.mem.span(_json_ptr);
            const owned = try std.heap.c_allocator.dupe(u8, _json_slice);
            break :blk owned;
        };
    }

    /// Seal this segment, producing an immutable `SegmentSeal` that commits to all
    /// segment metadata. The `Segment` is consumed — no further entries can be appended.
    pub fn seal(self: *Segment) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_segment_seal(handle);
        self._handle = 0;
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            const value = _result;
            defer c.hacienda_segment_seal_free(value);
            const _json_ptr = c.hacienda_segment_seal_to_json(value) orelse return error.OutOfMemory;
            defer c.hacienda_free_string(_json_ptr);
            const _json_slice = std.mem.span(_json_ptr);
            const owned = try std.heap.c_allocator.dupe(u8, _json_slice);
            break :blk owned;
        };
