    /// Unique identifier for this segment.
    pub fn id(self: *Segment) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_segment_id(handle);
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    /// The node that owns this segment.
    pub fn node_id(self: *Segment) error{ OutOfMemory, HandleClosed }!NodeId {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_segment_node_id(handle);
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk NodeId{ ._handle = _result };
        };
    }

    /// The tenant this segment belongs to.
    pub fn tenant_id(self: *Segment) error{ OutOfMemory, HandleClosed }!TenantId {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_segment_tenant_id(handle);
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk TenantId{ ._handle = _result };
        };
    }

    /// Chain hash of the most recent entry, or `GENESIS_HASH` when empty.
    pub fn tip(self: *Segment) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_segment_tip(handle);
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
