    ///
    /// **Errors:**
    ///
    /// - `AuditError.ConfigMismatch` — the entry was minted under a different config.
    /// - `AuditError.ChainIntegrity` — the entry's chain hash does not follow the tip.
    pub fn append(self: *Segment, entry: []const u8) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const entry_z = try std.heap.c_allocator.dupeSentinel(u8, entry, 0);
        defer std.heap.c_allocator.free(entry_z);
        const entry_handle = c.hacienda_audit_entry_from_json(entry_z.ptr);
        if (entry_handle == 0) return error.UnknownFfiError;
        defer c.hacienda_audit_entry_free(entry_handle);
        _ = c.hacienda_segment_append(handle, entry_handle);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
    }

    /// Verify the internal entry chain — delegates to `AuditChain.verify`, unchanged.
    ///
    /// This confirms that no entry within this segment was tampered with. It says nothing
    /// about the link to adjacent segments; use `verify_seal_chain` for that.
    pub fn verify(self: *Segment) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        _ = c.hacienda_segment_verify(handle);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *Segment) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.hacienda_segment_free(handle);
    }
};

