pub fn new_tenant_id(id: []const u8) error{ OutOfMemory, UnknownFfiError, Cancelled }!TenantId {
    const id_z = try std.heap.c_allocator.dupeSentinel(u8, id, 0);
    defer std.heap.c_allocator.free(id_z);
    const _handle = c.hacienda_tenant_id_new(id_z.ptr);
    if (_handle == 0) return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    return .{ ._handle = _handle };
}

