pub fn default_tenant_tenant_id() error{ OutOfMemory, UnknownFfiError, Cancelled }!TenantId {
    const _handle = c.hacienda_tenant_id_default_tenant();
    if (_handle == 0) return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    return .{ ._handle = _handle };
}

/// The identifier every store-level cloisonnement check keys off.
///
/// Two tenants are never comparable for access purposes: a resource that does not belong
/// to the calling tenant is reported as absent (404), never forbidden (403) — see
/// decision D-S1-6. `TenantId` is intentionally opaque (no ordering, no arithmetic) so
/// nothing can be tempted to derive one tenant's identifier from another's.
pub const TenantId = struct {
    _handle: u64,

    /// The underlying identifier string.
    pub fn as_str(self: *TenantId) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.hacienda_tenant_id_as_str(handle);
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.hacienda_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *TenantId) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.hacienda_tenant_id_free(handle);
    }
};

pub fn new_tenant_pseudonymiser_registry() error{ OutOfMemory, UnknownFfiError, Cancelled }!TenantPseudonymiserRegistry {
    const _handle = c.hacienda_tenant_pseudonymiser_registry_new();
    if (_handle == 0) return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
    return .{ ._handle = _handle };
}

/// Per-tenant cache of resolved `Pseudonymiser`s.
///
/// A `Pseudonymiser` eagerly resolves and caches all its key material at construction
/// (decision D-S1-4: fail at admission, never at first use). Multi-tenancy widens
/// "construction" from "process startup" to "tenant admission" — this registry is where
/// that admission happens, once per tenant, so a request never pays a resolver
/// round-trip and a tenant with broken key configuration is refused before it can
/// process any content, not discovered mid-request.
///
/// Lock poisoning is recovered from, not propagated as a panic: every access below
/// takes the guard with `.unwrap_or_else(PoisonError.into_inner)` rather than
/// `.expect(..)`. A panic while holding this lock can only occur inside a plain
/// `HashMap` read/insert, which leaves the map itself in a valid state even if some
/// unrelated code panicked mid-access elsewhere while holding it — so treating poison
/// as fatal here would only turn one thread's panic into every future tenant lookup
/// panicking too, for no added safety.
pub const TenantPseudonymiserRegistry = struct {
    _handle: u64,

    /// Resolve and cache `tenant`'s pseudonymiser.
    ///
    /// Idempotent, and safe to call again for an already-admitted tenant — the existing
    /// entry is replaced with a freshly resolved one. That is the path a key rotation
    /// takes (see P3): re-admit the tenant after the resolver reports a new active key.
    ///
    /// **Errors:**
    ///
    /// Whatever `resolver` returns for a missing or malformed key — see
    /// `Pseudonymiser.new` / `Pseudonymiser.with_active`.
    pub fn admit(self: *TenantPseudonymiserRegistry, tenant: TenantId, resolver: KeyResolver, active: ?KeyId, retired: []const u8) (error{ OutOfMemory, UnknownFfiError, Cancelled } || error{ OutOfMemory, HandleClosed })!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const retired_z = try std.heap.c_allocator.dupeSentinel(u8, retired, 0);
        defer std.heap.c_allocator.free(retired_z);
        _ = c.hacienda_tenant_pseudonymiser_registry_admit(handle, tenant_handle, resolver, active, retired_z);
        if (c.hacienda_last_error_code() != 0) {
            return _error_with_message(error{ OutOfMemory, UnknownFfiError, Cancelled });
        }
    }

    /// The admitted pseudonymiser for `tenant`, if any.
    ///
    /// `null` means the tenant was never admitted (or its last admission attempt
    /// failed and nothing was cached) — a caller must treat this the same as
    /// "pseudonymization is not configured for this tenant", never invent a key.
    pub fn get(self: *TenantPseudonymiserRegistry, tenant: TenantId) error{ OutOfMemory, HandleClosed }!?Pseudonymiser {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_tenant_pseudonymiser_registry_get(handle, tenant_handle);
        return if (_result == 0) null else Pseudonymiser{ ._handle = _result };
    }

    /// Whether `tenant` has been admitted.
    pub fn contains(self: *TenantPseudonymiserRegistry, tenant: TenantId) error{ OutOfMemory, HandleClosed }!bool {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const tenant_handle = tenant._handle;
        if (tenant_handle == 0) return error.HandleClosed;
        const _result = c.hacienda_tenant_pseudonymiser_registry_contains(handle, tenant_handle);
        return _result != 0;
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *TenantPseudonymiserRegistry) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.hacienda_tenant_pseudonymiser_registry_free(handle);
    }
};

